const SUP_CUSTOM='Custom (enter geometry)';

const SUP_MODEL=(k,name)=>SUPPORT.models.find(m=>m.kind===k&&m.name===name)||SUP_DEFAULT(k);

const MIG_MEM_MAP7={1:1,2:2,3:4,4:4};

const MIG_MEM_MAP4={1:1,2:2};

const KIND_LABEL={embed:'Embeddings',rerank:'Reranker',asr:'ASR',tts:'TTS',ocr:'OCR',guard:'Guard'};

const uv=(f,id)=>{ const c=FIELDS[id]; const raw=(f[id]===''||f[id]==null)? c.val : +f[id];
  const v=isFinite(raw)? raw : c.val; return Math.min(c.max, Math.max(c.min, v)); };

const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

const sliceName=(sl,plural)=> sl.kind==='cpx'? `GPU partition${plural?'s':''}` : `MIG ${sl.units}g slice${plural?'s':''}`;

const TS_PROJECT={name:1,gpu:1,perw:1,resil:1,mfu:1,mbu:1,ic:1,ovh:1,util:1,mode:1};

const TS_CARD={model:1,quant:1,kv:1,preset:1,seq:1,cache:1,out:1,reason:1,extend:1,
  conc:1,users:1,batch:1,policy:1,ttft:1,tps:1,p95:1,isolate:1,supports:1,
  turns:1,calls:1,burst:1,dur:1,callmin:1,tokmin:1,prompt:1,basis:1};

const TS_SUP=['embed','rerank','asr','tts','ocr','guard'];

/*ENGINE-START*/
function compute(s){
  const bw = s.bytesW, bk = s.bytesK;
  const weights = s.params * bw;
  const effSeq = s.resident + (s.extend ? s.reasonTok : 0);
  // KV per token. Models that mix full-attention layers with sliding-window
  // layers cost far less per token than their raw head geometry suggests: the
  // window layers only ever hold `kvWin` tokens, so their share shrinks as the
  // sequence grows. kvGlobal/kvWin absent = the classic uniform-attention form.
  const kvL = Math.max(1, s.kvLayers || s.layers);
  const kvGlobal = Math.min(kvL, Math.max(0, s.kvGlobal||0));
  const kvWin = Math.max(0, s.kvWin||0);
  const kvTok = (kvGlobal>0 && kvWin>0)
    ? ( kvGlobal * (s.kvgKeyOnly?1:2) * (s.kvgHeads||s.kvHeads) * (s.kvgDim||s.headDim)
        + (kvL-kvGlobal) * 2 * s.kvHeads * s.headDim * Math.min(1, kvWin/Math.max(1,effSeq))
      ) * bk / 1e9
    : 2 * kvL * s.kvHeads * s.headDim * bk / 1e9;
  const replicas = Math.max(1, Math.floor(s.gpus / Math.max(s.tp,1)));
  const active = s.policy === 'all' ? s.concurrent
               : Math.min(s.concurrent, s.batch * replicas);
  /* Prefix caching. `cachePct` is the share of the RESIDENT sequence that is
     byte-identical across concurrent requests: a system prompt, a tool schema,
     a few-shot block. A server with automatic prefix caching computes those
     blocks once and reuses them, which has two separate consequences, and the
     model must keep them separate:
       prefill  only the uncached remainder is prefilled, so TTFT scales down
       memory   the shared blocks are stored ONCE per replica, not once per
                admitted request
     Decode is deliberately NOT discounted: every request still attends over its
     whole context each step, so the per-step read stays effSeq. Shared-prefix
     (cascade) attention kernels can beat that; treating it as free here would
     make the estimate optimistic, and this tool errs the other way. */
  const cacheFrac = Math.min(0.95, Math.max(0, s.cachePct || 0));
  const cachedTok = Math.floor(s.resident * cacheFrac);
  const uniqueSeq = Math.max(0, effSeq - cachedTok);
  const kvShared = cachedTok * kvTok;
  const kvTotal = active * uniqueSeq * kvTok + replicas * kvShared;
  const act = Math.min(effSeq, 8192) * s.hidden * 12 * bw / 1e9;
  /* NCCL buffers live in a communicator, and a communicator is one tensor-parallel
     replica. Charging (poolGPUs - 1) billed independent replicas for talking to
     each other: 40 TP1 replicas paid 585 GB to communicate with nobody. */
  const fixed = 5, multi = replicas * Math.max(0, Math.max(s.tp,1) - 1) * (s.multiGb != null ? s.multiGb : 15);
  const weightsAll = replicas * weights, actAll = replicas * act;
  const total = weightsAll + kvTotal + actAll + fixed + multi;
  const servingGpus = replicas * Math.max(s.tp,1), idleGpus = s.gpus - servingGpus;
  const avail = servingGpus * s.gpuVram;
  const bwEff = s.gpuBw * s.tp * s.ic * s.mbu * 1000;
  const batchPerRep = Math.max(1, active / replicas);
  const tps = bwEff / (s.active * bw + batchPerRep * effSeq * kvTok);
  const agg = tps * active;
  const prefillTok = Math.max(0, s.resident - cachedTok);
  const ttft = 2 * prefillTok * s.active / (s.gpuTflops * s.tp * s.mfu);
  const itl = 1000 / tps;
  const genTok = s.reasonTok + s.visibleOut;
  const latency = (ttft + s.ovh) / 1000 + genTok / tps;
  const p95 = latency * 1.3;
  // one more admitted call costs only its UNIQUE tokens once the prefix is shared
  const maxBatchMem = Math.max(0, Math.floor((avail - weightsAll - actAll - fixed - multi - replicas*kvShared) / (uniqueSeq * kvTok || 1e-9) / replicas)) || 0;
  const kvDelta = uniqueSeq * kvTok;
  const allActiveVram = weightsAll + s.concurrent * uniqueSeq * kvTok + replicas * kvShared + actAll + fixed + multi;
  const queued = Math.max(0, s.concurrent - active);
  const fits = total <= avail;
  const slo = {
    ttft: s.sloTtft > 0 ? {on:true, pass: ttft <= s.sloTtft} : {on:false, pass:true},
    tps:  s.sloTps  > 0 ? {on:true, pass: tps  >= s.sloTps } : {on:false, pass:true},
    p95:  s.sloP95  > 0 ? {on:true, pass: p95  <= s.sloP95 } : {on:false, pass:true},
  };
  const sloAll = slo.ttft.pass && slo.tps.pass && slo.p95.pass;
  return {weights,weightsAll,kvTok,effSeq,uniqueSeq,cachedTok,kvShared,prefillTok,
          replicas,active,kvTotal,act,actAll,fixed,multi,total,avail,
          servingGpus,idleGpus,bwEff,batchPerRep,tps,agg,ttft,itl,latency,p95,genTok,maxBatchMem,kvDelta,
          allActiveVram,queued,fits,slo,sloAll,headroom:avail-total};
}
/*ENGINE-END*/

function fmt(x){ if(!isFinite(x)) return '—';
  const a=Math.abs(x);
  return a>=1000 ? Math.round(x).toLocaleString('en-US')
       : a>=100 ? x.toFixed(0) : a>=10 ? x.toFixed(1) : x.toFixed(2);
}

function fmtTok(x){ return x>=1048576? (x/1048576).toFixed(x%1048576?1:0)+'M' : x>=1024? (x/1024).toFixed(x%1024?1:0).replace(/\.0$/,'')+'K' : String(Math.round(x)); }

/* the two KV terms the engine sums, exposed so the Excel export can mirror it */
function kvgElem(s){ const L=Math.max(1,s.kvLayers||s.layers), g=Math.min(L,Math.max(0,s.kvGlobal||0));
  return (g>0&&(s.kvWin||0)>0)? g*(s.kvgKeyOnly?1:2)*(s.kvgHeads||s.kvHeads)*(s.kvgDim||s.headDim)
    : 2*L*s.kvHeads*s.headDim; }

function kvlElem(s){ const L=Math.max(1,s.kvLayers||s.layers), g=Math.min(L,Math.max(0,s.kvGlobal||0));
  return (g>0&&(s.kvWin||0)>0)? (L-g)*2*s.kvHeads*s.headDim : 0; }

/* A support entry either names a library model or carries its own geometry. The
   sizing only ever needs two numbers from it, VRAM per instance and how many
   concurrent streams one instance serves, so a house ASR or a TTS nobody has
   published figures for is a first-class citizen rather than a missing row. */
function supSpec(sp){
  if(!sp) return null;
  if(sp.custom) return {kind:sp.kind, name:(sp.custom.name||'Custom '+sp.kind),
    params:+sp.custom.params||0, vram:Math.max(0.05,+sp.custom.vram||1),
    cap:Math.max(1,+sp.custom.cap||10), note:'custom entry', custom:true};
  return SUP_MODEL(sp.kind, sp.model);
}

function defaultSupports(ci){ const c=CASES[ci]; if(!c||!c.supports) return [];
  return c.supports.map(k=>{ const d=SUP_DEFAULT(k); return d? {kind:k, model:d.name, on:true} : null; }).filter(Boolean); }

function ucName(u){ if(u.name) return u.name;
  const ci=+u.f.selCase; if(ci>=0&&CASES[ci]) return CASES[ci].name;
  return ucModelName(u); }

function ucModelName(u){ return u.f.chkCustom? 'Custom model' : ((MODELS[+u.f.selModel||0]||{}).name||'?'); }

function poolKey(u){ const f=u.f;
  const mk=f.chkCustom? 'custom:'+[f.cusParams,f.cusActive,f.cusHidden,f.cusLayers,f.cusKvh,f.cusHdim].join(',') : 'm'+(+f.selModel||0);
  return mk+'|q'+(+f.selWQuant||0)+'|k'+(+f.selKQuant||0)+'|p'+(f.selPolicy||''); }

function sliceProfiles(g){
  const part=g.part||{};
  const out=[];
  if(part.kind==='mig'){
    const map = part.max===7? MIG_MEM_MAP7 : part.max===4? MIG_MEM_MAP4 : null;
    if(!map) return out;
    const memSlices = part.max===7? 8 : 4;
    for(const uStr of Object.keys(map)){
      const u=+uStr, m=map[u];
      const gb=Math.floor(g.vram*m/memSlices);
      out.push({units:u, max:part.max, gb, bw:g.bw*(m/memSlices)*0.93, tflops:g.tflops*(u/part.max), kind:'mig'});
    }
  } else if(part.kind==='cpx'){
    // AMD compute partitioning is uniform per GPU: only the single-XCD partition exists
    out.push({units:1, max:part.max, gb:part.min, bw:g.bw*(1/part.max), tflops:g.tflops*(1/part.max), kind:'cpx'});
  }
  return out;
}

/* bin capacity and per-slice cost in the units that physically constrain packing:
   7-slice MIG parts fill their 8 MEMORY slices first (a 3g takes 4 of 8), so
   3g+3g+1g is impossible even though 3+3+1 compute units fit; 4-slice MIG and
   cpx parts have memory == compute units. */
function binCap(part){ return part&&part.kind==='mig'&&part.max===7? 8 : (part&&part.max)||1; }

function sliceCost(part,u){ return part&&part.kind==='mig'&&part.max===7? (MIG_MEM_MAP7[u]||8) : u; }

function readHw(){
  const g=GPUS[+$('selGpu').value||0];
  const fv=id=>{ const c=FIELDS[id]; const raw=$(id).value===''? c.val : +$(id).value;
    const v=isFinite(raw)? raw : c.val; return Math.min(c.max, Math.max(c.min, v)); };
  return {g, perW:Math.round(fv('inPerW')), resil:$('selResil').value,
    mfu:fv('inMfu'), mbu:fv('inMbu'), ic:fv('inIc'), ovh:fv('inOvh')};
}

/* An exact card count is an auto-size OUTPUT, valid only for the inputs it was
   solved against. Stamp it, and fall back to whole nodes the moment anything it
   depended on moves, so a stale allocation can never quietly misfit. */
function cardsKey(u, hw){ const f=u.f||{};
  return [f.chkCustom? 'C'+[f.cusParams,f.cusActive,f.cusHidden,f.cusLayers,f.cusKvh,f.cusHdim,f.cusCtx].join('.') : 'M'+f.selModel,
    f.selWQuant, f.selKQuant, hw.g.name, hw.perW, f.inTp, f.selPolicy, f.chkExtend?1:0,
    Math.round(uv(f,'inConc')), Math.round(uv(f,'inSeq')), Math.round(uv(f,'inOut')),
    Math.round(uv(f,'inReasonTok')), Math.round(uv(f,'inCache')), f.sloTtft, f.sloTps, f.sloP95,
    (($('autoUtil')&&$('autoUtil').value)||80)].join('|'); }

function ucState(u, hw){
  hw=hw||readHw(); const f=u.f;
  const m=f.chkCustom? {name:'Custom', params:+f.cusParams||0.1, active:+f.cusActive||0.1,
      hidden:+f.cusHidden||64, layers:+f.cusLayers||1, kvHeads:+f.cusKvh||1,
      headDim:+f.cusHdim||8, ctx:+f.cusCtx||1024, arch:'Custom', dev:'—', url:''}
    : (MODELS[+f.selModel||0]||MODELS[0]);
  const wq=QUANTS[+f.selWQuant||0]||QUANTS[0], kq=KV_QUANTS[+f.selKQuant||0]||KV_QUANTS[0];
  const workers=Math.round(uv(f,'inWorkers'));
  // auto-size allocates cards, not nodes: pools pack onto shared nodes, so a
  // pool may own any number of GPUs. Anything that invalidates the plan (a hand
  // edit, a different model, GPU, precision or demand) returns it to whole nodes.
  const fresh=(+u.cards>0) && u.cardsKey===cardsKey(u,hw);
  const gpus=Math.max(1, fresh? +u.cards : workers*hw.perW);
  const tp=Math.min(Math.round(uv(f,'inTp')), gpus);
  return {model:m, gpu:hw.g, wq, kq,
    params:m.params, active:m.active, hidden:m.hidden, layers:m.layers,
    kvHeads:m.kvHeads, headDim:m.headDim, ctx:m.ctx,
    kvGlobal:m.kvGlobal, kvWin:m.kvWin, kvgHeads:m.kvgHeads, kvgDim:m.kvgDim, kvgKeyOnly:m.kvgKeyOnly, kvLayers:m.kvLayers,
    bytesW:wq.bytes, bytesK:kq.bytes,
    resident:Math.round(uv(f,'inSeq')), cachePct:uv(f,'inCache')/100, visibleOut:Math.round(uv(f,'inOut')),
    reasonMode:f.selReason||'None', reasonTok:Math.round(uv(f,'inReasonTok')),
    extend:!!f.chkExtend,
    concurrent:Math.round(uv(f,'inConc')), batch:Math.round(uv(f,'inBatch')),
    policy:f.selPolicy||'run',
    workers, perW:hw.perW, gpus, tp, resil:hw.resil,
    gpuVram:hw.g.vram, gpuBw:hw.g.bw, gpuTflops:hw.g.tflops,
    // the cross-node penalty belongs to the pool whose copy actually spans
    // workers, not to the whole project: one wide model must not tax every
    // other model's decode speed
    mfu:hw.mfu, mbu:hw.mbu, ic:(tp>hw.perW? Math.min(hw.ic,0.7) : hw.ic), ovh:hw.ovh,
    sloTtft:+f.sloTtft||0, sloTps:+f.sloTps||0, sloP95:+f.sloP95||0};
}

function poolState(pool, hw){
  const states=pool.members.map(i=>ucState(UC[i], hw));
  const base=states[0];
  const conc=states.reduce((t,s)=>t+s.concurrent,0)||1;
  const wavg=get=>states.reduce((t,s)=>t+get(s)*s.concurrent,0)/conc;
  // The card allocation belongs to the POOL, so a stamp that is stale for ANY
  // member is stale for all of them. Reading only member 0's verdict meant the
  // same edit gave two different fleets depending on which row you typed in.
  const freshAll=pool.members.every(i=>{ const u=UC[i];
    return (+u.cards>0) && u.cardsKey===cardsKey(u,hw); });
  const gpus=freshAll? base.gpus : Math.max(1, base.workers*hw.perW);
  return Object.assign({}, base, {
    gpus, tp:Math.min(base.tp, gpus),
    concurrent:conc,
    resident:Math.round(wavg(s=>s.resident)),
    cachePct:wavg(s=>s.cachePct||0),
    visibleOut:Math.round(wavg(s=>s.visibleOut)),
    reasonTok:Math.round(wavg(s=>s.extend||s.reasonTok>0? s.reasonTok:0)),
    extend:states.some(s=>s.extend&&s.reasonTok>0),
    batch:Math.max.apply(null, states.map(s=>s.batch)),
    sloTtft:0,
    sloTps:Math.max.apply(null, states.map(s=>s.sloTps).concat([0])),
    sloP95:0,
    // per-member request shapes: the solver checks each use case's OWN prefill and
    // output against its OWN targets; the blended fields above stay for memory
    // and mix decode-step math only. Without this, one member's strict target
    // gets priced against another member's long context or thinking budget.
    members: pool.members.map((idx,k)=>{ const s2=states[k];
      return {name:ucName(UC[idx]), conc:s2.concurrent, resident:s2.resident,
        cachePct:s2.cachePct||0,
        visibleOut:s2.visibleOut, reasonTok:s2.reasonTok, extend:s2.extend,
        sloTtft:+s2.sloTtft||0, sloTps:+s2.sloTps||0, sloP95:+s2.sloP95||0}; }),
  });
}

/* Whole-GPU co-residency: in practice several models share the same physical
   GPUs (vLLM memory fractions, Triton multi-model, MPS), which is why real
   clusters are not one-model-per-card. Two limits decide whether a card can
   hold another tenant:
     memory   Σ per-GPU footprints <= the auto-size memory target
     bandwidth decode is memory-bandwidth bound, so a pool that reaches `tps`
              alone but only owes `sloTps` consumes sloTps/tps of the card;
              tenants may share only while those fractions sum under 1.
   A pool with no speed target is throughput-hungry (it will use whatever it
   gets), so it never shares. TP replicas take an aligned block of tp GPUs:
   the shards stay peers on one NVLink island, they just co-tenant the cards
   with another model instead of owning them. */
function coDuty(p){
  const t=+p.state.sloTps||0, tps=p.d.tps||0;
  if(!(t>0) || !(tps>0)) return 1;            // no target: assume it wants it all
  return Math.min(1, t/tps);
}

function coPack(pools, hw){
  const packPct=Math.min(95,Math.max(50,+($('autoUtil')&&$('autoUtil').value)||80))/100;
  const cap=packPct*hw.g.vram, DUTY_CAP=0.95;  // prefill contention is checked explicitly below
  const items=[];
  pools.forEach((p,pi)=>{ if(p.sliced) return;
    const tp=Math.max(1,p.state.tp), gpus=Math.max(1,p.d.replicas*tp);
    const mem=p.d.total/gpus, duty=coDuty(p), safe=coShareSafe(p), tslack=coTtftSlack(p), p95At=coP95At(p);
    for(let r=0;r<p.d.replicas;r++) items.push({pool:pi, rep:r, tp, mem, duty, safe, tslack, p95At});
  });
  // widest TP first so aligned blocks nest, then heaviest cards first
  items.sort((a,b)=> b.tp-a.tp || b.mem-a.mem);
  const gpus=[];
  const grow=n=>{ while(gpus.length<n) gpus.push({mem:0, duty:0, slots:[]}); };
  // Why a merge was refused, recorded WHERE it was refused. Rebuilding the
  // reason afterwards from the three per-pool gates could not express the two
  // that actually reject blocks (memory and decode duty), so a bandwidth-bound
  // fleet was blamed on first-token headroom.
  const why=[];   // {a, b, t, need, cap} per rejected pairing, most-informative first
  const RANK={duty:0, mem:1, ttft:2, unsafe:3, samePool:4};
  items.forEach(it=>{
    let placed=false, best=null;
    if(it.safe){
      const limit=gpus.length;                       // only consider existing cards
      for(let b=0; b+it.tp<=limit; b+=it.tp){
        const block=gpus.slice(b, b+it.tp);
        // a card already carrying this pool gains nothing from another of its
        // replicas: real stacks raise the batch instead of running two servers
        const samePool=block.some(g=>g.slots.some(s=>s.pool===it.pool));
        const allSafe=block.every(g=>g.slots.every(s=>s.safe));
        const roomy=block.every(g=>g.mem+it.mem<=cap+1e-9 && g.duty+it.duty<=DUTY_CAP+1e-9);
        // sharing a card also shares its prefill: every tenant's first token
        // stretches by roughly 1/(1 - what the neighbours take). Merge only
        // while each tenant, incoming one included, still meets its TTFT.
        const ttftOk=block.every(g=>{
          const tot=g.duty+it.duty;
          const infl=t=>{ const others=Math.min(0.99, tot-t); return 1/(1-others); };
          const mine=infl(it.duty);
          if(mine > it.tslack || !it.p95At(mine)) return false;
          return g.slots.every(s=>{ const f=infl(s.duty);
            return f <= s.tslack && (!s.p95At || s.p95At(f)); });
        });
        if(roomy&&allSafe&&!samePool&&ttftOk){ block.forEach((g,k)=>{ g.mem+=it.mem; g.duty+=it.duty;
          g.slots.push({pool:it.pool, rep:it.rep, shard:k, mem:it.mem, duty:it.duty, safe:it.safe, tslack:it.tslack, p95At:it.p95At}); });
          placed=true; break; }
        // the block that came closest names the binding limit for this pairing
        if(!block.some(g=>g.slots.length)) continue;
        // name the tenant that is actually in the way (the heaviest on the
        // blocking card), not whichever happened to land there first
        const host=block.reduce((w,g)=>(g.duty>w.duty? g:w), block[0]);
        const hostSlot=(host.slots||[]).slice().sort((x,y)=>y.duty-x.duty)[0]||{};
        const hostPool=hostSlot.pool!=null? hostSlot.pool : it.pool;
        const maxMem=Math.max.apply(null, block.map(g=>g.mem))+it.mem;
        const maxDuty=Math.max.apply(null, block.map(g=>g.duty))+it.duty;
        // a card that already runs this very pool is refused for that reason,
        // whatever else is also true of it
        const t = samePool&&hostPool===it.pool? 'samePool'
          : maxDuty>DUTY_CAP+1e-9? 'duty'
          : maxMem>cap+1e-9? 'mem'
          : !allSafe? 'unsafe'
          : samePool? 'samePool' : 'ttft';
        const cand={a:it.pool, b:hostPool, t, duty:maxDuty, mem:maxMem};
        if(!best || RANK[cand.t]<RANK[best.t]) best=cand;
      }
      if(!placed&&best) why.push(best);
    }
    if(!placed){ // fresh aligned block: the first tenant always fits its own card
      const b=Math.ceil(gpus.length/it.tp)*it.tp; grow(b+it.tp);
      gpus.slice(b, b+it.tp).forEach((g,k)=>{ g.mem+=it.mem; g.duty+=it.duty;
        g.slots.push({pool:it.pool, rep:it.rep, shard:k, mem:it.mem, duty:it.duty, safe:it.safe, tslack:it.tslack, p95At:it.p95At}); }); }
  });
  const used=gpus.filter(g=>g.slots.length);
  // why no card took a second tenant, in order of how many pairings each limit
  // blocked: the pool-level gates first (a pool that can never share), then the
  // pairwise limits actually measured during placement.
  const blockers=[], poolGates=[], shared1=new Set();
  used.forEach(g=>{ if(new Set(g.slots.map(s=>s.pool)).size>1) g.slots.forEach(s=>shared1.add(s.pool)); });
  // two pools of the same model are a real configuration: add the width, and an
  // ordinal when even that collides, so a reason always points at ONE of them
  const nm=pi=>{ const p=pools[pi]; if(!p) return 'a pool';
    const n=p.state.model.name;
    const sameName=pools.filter((q,qi)=>!q.sliced&&q.state.model.name===n);
    if(sameName.length<2) return n;
    const sameTp=sameName.filter(q=>q.state.tp===p.state.tp);
    if(sameTp.length<2) return `${n} (TP${p.state.tp})`;
    return `${n} (TP${p.state.tp}, pool ${pi+1})`; };
  pools.forEach((p,pi)=>{ if(p.sliced) return;
    if(!(+p.state.sloTps>0)){ poolGates.push(`${nm(pi)} has no per-user speed target, so there is no share to guarantee it`); return; }
    if(!coShareSafe(p)) poolGates.push(`${nm(pi)} would miss its P95 at the speed a shared card guarantees`);
  });
  { const tally={};
    why.forEach(w=>{ const k=w.t+'|'+Math.min(w.a,w.b)+'|'+Math.max(w.a,w.b);
      if(!tally[k]) tally[k]={...w, n:0}; tally[k].n++; });
    Object.values(tally).sort((x,y)=>y.n-x.n).slice(0,3).forEach(w=>{
      // a pool that did merge somewhere is not blocked, whatever a later pairing said
      if(shared1.has(w.a)) return;
      if(w.t==='duty') blockers.push(`${nm(w.a)} and ${nm(w.b)} together would need ${Math.round(w.duty*100)}% of one card's decode bandwidth, over the ${Math.round(DUTY_CAP*100)}% ceiling`);
      else if(w.t==='mem') blockers.push(`${nm(w.a)} and ${nm(w.b)} together need ${fmt(w.mem)} GB on a card budgeted to ${fmt(cap)} GB`);
      else if(w.t==='ttft') blockers.push(`sharing a card would stretch the first token of ${nm(w.a)} or ${nm(w.b)} past its target`);
      else if(w.t==='unsafe') blockers.push(`${nm(w.b)} cannot hold its P95 at the speed a shared card guarantees, so nothing may join its cards`);
      else blockers.push(`only cards already running ${nm(w.a)} had room, and two replicas of one model on a card add nothing`);
    });
    // measured pairings first, generic pool gates after: the note prints
    // blockers[0] as THE reason, and it used to be whichever gate came first
    poolGates.forEach(g2=>blockers.push(g2)); }
  const dedicatedG=pools.reduce((t,p)=>t+(p.sliced?0:p.d.replicas*Math.max(1,p.state.tp)),0);
  return {gpus:used, count:used.length, dedicatedG, saved:Math.max(0,dedicatedG-used.length),
    blockers:[...new Set(blockers)],
    shares:used.filter(g=>new Set(g.slots.map(s=>s.pool)).size>1).length};
}

function allocSupports(hw){
  const g=hw.g, part=g.part||{kind:'frac'};
  const agg={};
  UC.forEach((u,idx)=>{ const conc=Math.round(uv(u.f,'inConc'));
    (u.supports||[]).forEach(sp=>{ const m=supSpec(sp); if(!m) return;
      const key=sp.kind+'|'+m.name;
      const a=agg[key]=agg[key]||{kind:sp.kind, model:m, demand:0, ucIdx:[]};
      a.demand+=conc; a.ucIdx.push(idx); }); });
  const items=Object.values(agg).map(a=>Object.assign({}, a,
    {instances:Math.max(1, Math.ceil(a.demand/a.model.cap))}));
  const totalVram=items.reduce((t,it)=>t+it.instances*it.model.vram,0);
  if(!items.length) return {items, gpus:0, mode:part.kind, layout:[], totalVram:0, note:''};
  const layout=[]; let note='';
  const sliceable = part.kind==='mig'||part.kind==='cpx';
  if(sliceable){
    // each support instance lands on the smallest REAL slice profile whose
    // memory holds it; models smaller than the smallest profile co-host several
    // instances per slice (they are VRAM-bound at this scale, so pack by memory).
    const profs=sliceProfiles(g);
    const smallest=profs[0]||{units:1, gb:part.min};
    items.forEach(it=>{
      if(it.model.vram>smallest.gb){
        const pfit=profs.find(pr=>pr.gb>=it.model.vram);
        it.units=pfit? pfit.units : part.max;   // nothing fits: takes the whole GPU
        it.sliceGb=pfit? pfit.gb : g.vram;
        it.perSlice=1; it.sliceCount=it.instances;
      } else {
        it.units=smallest.units; it.sliceGb=smallest.gb;
        it.perSlice=Math.max(1, Math.floor(smallest.gb/it.model.vram));
        it.sliceCount=Math.ceil(it.instances/it.perSlice);
      } });
    const cap=binCap(part);
    items.slice().sort((x,y)=>sliceCost(part,y.units)-sliceCost(part,x.units)).forEach(it=>{
      const mu=sliceCost(part, it.units);
      for(let n=0;n<it.sliceCount;n++){
        const inst=Math.min(it.perSlice, it.instances-n*it.perSlice);
        let bin=layout.find(b=>b.used+mu<=cap);
        if(!bin){ bin={used:0, slices:[]}; layout.push(bin); }
        bin.used+=mu;
        bin.slices.push({kind:it.kind, model:it.model.name, gb:it.sliceGb, n:it.units, mu, inst,
          use:Math.min(it.sliceGb, inst*it.model.vram)});
      } });
    note = part.kind==='mig'
      ? `isolated MIG slices (${part.max} per GPU, ${part.min} GB granularity)`
      : `isolated compute partitions (${part.max} per GPU, ${part.min} GB each)`;
  } else {
    const cap = part.kind==='whole'? g.vram : 0.9*g.vram;
    items.slice().sort((x,y)=>y.model.vram-x.model.vram).forEach(it=>{
      for(let n=0;n<it.instances;n++){
        let bin=layout.find(b=>b.used+it.model.vram<=cap);
        if(!bin){ bin={used:0, slices:[]}; layout.push(bin); }
        bin.used+=it.model.vram;
        bin.slices.push({kind:it.kind, model:it.model.name, gb:it.model.vram, n:0, use:it.model.vram});
      } });
    note = part.kind==='whole'
      ? `whole-card granularity: ${g.name} has no partitioning; co-residency within one card only via one serving container`
      : `fractional sharing (time-slice / MPS): no memory or fault isolation on ${g.name}`;
  }
  return {items, gpus:layout.length, mode:part.kind, layout, totalVram, note};
}

function computeProject(){
  const hw=readHw();
  const pools=[];
  UC.forEach((u,i)=>{ const k=u.isolate? 'iso:'+u.id : poolKey(u);
    let p=pools.find(x=>x.key===k); if(!p){ p={key:k, members:[]}; pools.push(p); }
    p.members.push(i); });
  pools.forEach(p=>{
    p.state=poolState(p, hw);
    const nzmin=(vals)=>{ const n=vals.filter(v=>v>0); return n.length? Math.min.apply(null,n) : 0; };
    p.state.sloTtft=nzmin(p.members.map(i=>+UC[i].f.sloTtft||0));
    p.state.sloP95=nzmin(p.members.map(i=>+UC[i].f.sloP95||0));
    // MIG-sliced pool: each replica lives on its own hardware slice, modeled as
    // a synthetic smaller GPU (compute u/max, bandwidth by memory-slice map,
    // per-instance overhead instead of whole-GPU multi overhead)
    const su=UC.length>1? (+((UC[p.members[0]]||{}).sliceU)||0) : 0;
    const prof=su>0&&p.state.tp===1? sliceProfiles(hw.g).find(pr2=>pr2.units===su) : null;
    if(prof){
      p.sliced=prof;
      Object.assign(p.state, {gpuVram:prof.gb, gpuBw:prof.bw, gpuTflops:prof.tflops,
        gpus:p.state.workers, perW:1, multiGb:1.4, ic:1});
    }
    p.d=compute(p.state);
    // demand cap: keep only the replicas the peak load needs; trimmed replicas
    // are simply not procured (the packed fleet buys serving GPUs, not copies
    // nobody asked for).
    // Trim replicas nobody's demand needs, but never below what the speed and
    // P95 targets already required: dropping replicas raises batch-per-replica,
    // which slows every user. The cap used to hand back a fleet that missed the
    // very targets it had just been grown to meet.
    const needReps=Math.max(1, Math.ceil(p.state.concurrent/Math.max(1,p.state.batch)));
    if(UC.length>1 && p.d.replicas>needReps){
      const trial=compute(Object.assign({}, p.state, {gpus:needReps*p.state.tp}));
      const ms=p.state.members||[];
      const keepsSlo=(p.state.sloTps>0? trial.tps>=p.state.sloTps : true)
        && trial.queued<=p.d.queued
        && ms.every(m=>{ if(!(+m.sloP95>0)) return true;
            const gen=(m.reasonTok||0)+(m.visibleOut||0);
            const pf=m.resident-Math.floor(m.resident*Math.min(0.95,Math.max(0,m.cachePct||p.state.cachePct||0)));
            const ttft=2*pf*p.state.active/(p.state.gpuTflops*Math.max(1,p.state.tp)*p.state.mfu);
            return 1.3*((ttft+p.state.ovh)/1000 + gen/Math.max(1e-6,trial.tps)) <= m.sloP95; });
      if(keepsSlo){ p.capped=p.d.replicas; p.d=trial; }
    }
    p.perUc=p.members.map(i=>{
      const s=ucState(UC[i], hw);
      s.tp=p.state.tp; s.workers=p.state.workers; s.gpus=p.d.replicas*p.state.tp; s.batch=p.state.batch;
      if(p.sliced) Object.assign(s,{gpuVram:p.sliced.gb, gpuBw:p.sliced.bw, gpuTflops:p.sliced.tflops, multiGb:1.4, ic:1, perW:1});
      const d=compute(s);
      const share=Math.min(s.concurrent, Math.round(p.d.active*s.concurrent/Math.max(1,p.state.concurrent)));
      return {i, uc:UC[i], s, d, share};
    });
  });
  const shared=allocShared(pools, hw);
  const co=coPack(pools, hw);
  const fleet=fleetTotals(pools, shared, hw, co);
  return {pools, sup:shared.sup, shared, co, fleet, hw};
}

/* A sliced pool carries the SLICE as its hardware in p.state, because that is
   what the engine needs to describe it. Any re-solve has to hand the solver a
   real card back, or it plans a slice onto a slice. */
function poolSolveState(p, hw, extra){
  const s=Object.assign({}, p.state);
  if(p.sliced) Object.assign(s, {gpuVram:hw.g.vram, gpuBw:hw.g.bw, gpuTflops:hw.g.tflops,
    perW:hw.perW, multiGb:15, ic:hw.ic, tp:1});
  return Object.assign(s, extra||{});
}

/* signature for anything that re-solves the whole project: every input the
   solver reads, so a memoised scan can never outlive the fleet it describes */
function prjSolveSig(prj){
  // Every field the solver reads has to be in here. A custom model is always
  // named "Custom", extend/selCase/tp/cards never appeared, and a memo that
  // outlives its inputs quotes a fleet that no longer exists.
  const geo=st=>[st.params,st.active,st.hidden,st.layers,st.kvHeads,st.headDim,st.ctx,
    st.kvGlobal||0,st.kvWin||0,st.kvgHeads||0,st.kvgDim||0,st.kvgKeyOnly?1:0,st.kvLayers||0].join('.');
  return prj.pools.map(p=>[p.state.model.name,geo(p.state),p.state.wq.name,p.state.kq.name,
      Math.round(p.state.concurrent),Math.round(p.state.resident),Math.round(p.state.visibleOut),
      Math.round(p.state.reasonTok),p.state.extend?1:0,p.state.policy,
      Math.round((p.state.cachePct||0)*100),
      p.state.tp,p.state.gpus,p.sliced? p.sliced.units:0,
      p.members.map(i=>[UC[i].f.selCase,UC[i].f.sloTtft,UC[i].f.sloTps,UC[i].f.sloP95,
        UC[i].f.chkExtend?1:0,(UC[i].supports||[]).map(sp=>sp.kind+':'
          +(sp.custom? `c${sp.custom.name}|${sp.custom.vram}|${sp.custom.cap}` : sp.model)).join('+')].join(',')).join(';')].join('/')).join('|')
    +'#'+[prj.hw.perW,prj.hw.g.name,prj.hw.ic,prj.hw.mbu,prj.hw.mfu,prj.hw.ovh,prj.hw.resil,
      (($('autoUtil')&&$('autoUtil').value)||80)].join('/');
}

function allocShared(pools, hw){
  const g=hw.g, part=g.part||{kind:'frac'};
  const sliceable = part.kind==='mig'||part.kind==='cpx';
  const sup=allocSupports(hw);
  if(!sliceable) return {sup, bins:sup.layout, gpus:sup.gpus, note:sup.note};
  // rebuild one unit-space packing: sliced-pool replicas first (bigger), then supports
  const items=[];
  pools.forEach((p,pi)=>{ if(!p.sliced) return;
    const fill=Math.min(1, p.d.total/Math.max(1,p.d.avail)), useGb=fill*p.sliced.gb;
    for(let r2=0;r2<p.d.replicas;r2++) items.push({kind:'pool', pool:pi, units:p.sliced.units,
      gb:p.sliced.gb, fill, tip:`${p.state.model.name} replica ${r2+1} · ${sliceName(p.sliced)} · ${fmt(useGb)} of ${fmt(p.sliced.gb)} GB slice memory (${Math.round(fill*100)}%)`}); });
  sup.layout.forEach(bin=>bin.slices.forEach(sl=>{ const fl=sl.use!=null? Math.min(1,sl.use/Math.max(1,sl.gb)) : null;
    items.push({kind:'sup', sub:sl.kind, model:sl.model,
      units:sl.n, gb:sl.gb, use:sl.use, fill:fl, inst:sl.inst,
      tip:`${KIND_LABEL[sl.kind]||sl.kind} ${sl.model}${sl.inst>1?' ×'+sl.inst:''} · ${fl!=null? fmt(sl.use)+' of '+fmt(sl.gb)+' GB slice memory ('+Math.round(fl*100)+'%)' : fmt(sl.gb)+' GB slice'}`}); }));
  const bins=[], cap=binCap(part);
  items.forEach(it=>{ it.mu=sliceCost(part, it.units); });
  items.sort((x,y)=>y.mu-x.mu).forEach(it=>{
    let bin=bins.find(b=>b.used+it.mu<=cap);
    if(!bin){ bin={used:0, slices:[]}; bins.push(bin); }
    bin.used+=it.mu; bin.slices.push(it); });
  return {sup, bins, gpus:bins.length,
    note:`isolated ${part.kind==='mig'?'MIG slices':'compute partitions'} (${part.max} per GPU): sliced model replicas and supporting models share physical GPUs`};
}

function coShareSafe(p){
  const st=p.state, t=+st.sloTps||0;
  if(!(t>0)) return false;
  const ms=(st.members&&st.members.length)? st.members : [{name:null, resident:st.resident,
    visibleOut:st.visibleOut, reasonTok:st.reasonTok, sloTtft:st.sloTtft, sloP95:st.sloP95}];
  return ms.every(m=>{
    if(!(+m.sloP95>0)) return true;
    const gen=(m.reasonTok||0)+(m.visibleOut||0);
    const ttft=2*m.resident*st.active/(st.gpuTflops*Math.max(1,st.tp)*st.mfu);
    return 1.3*((ttft+st.ovh)/1000 + gen/t) <= m.sloP95;
  });
}

/* A pool may only co-tenant a card if it still meets its targets at the speed
   it is GUARANTEED under sharing, which is its own target rather than the solo
   speed it gets with the card to itself. Latency is the trap: a pool can pass
   P95 comfortably at 95 tok/s alone and fail it at the 40 tok/s it is merely
   promised. Pools without a speed target have no guaranteed share at all, so
   they never share. */
function coTtftSlack(p){
  const st=p.state;
  const ms=(st.members&&st.members.length)? st.members : [{resident:st.resident, sloTtft:st.sloTtft}];
  let slack=Infinity;
  ms.forEach(m=>{ if(!(+m.sloTtft>0)) return;
    const solo=2*m.resident*st.active/(st.gpuTflops*Math.max(1,st.tp)*st.mfu);
    slack=Math.min(slack, solo>0? m.sloTtft/solo : Infinity); });
  return slack;
}

/* P95 under sharing: the prefill stretches by the same factor the TTFT check
   uses, and the tenant only ever gets its target decode speed. Judging P95 on
   the solo first-token time let a merge ship a card that misses it. */
function coP95At(p){
  const st=p.state, t=+st.sloTps||0;
  const ms=(st.members&&st.members.length)? st.members : [{resident:st.resident,
    visibleOut:st.visibleOut, reasonTok:st.reasonTok, sloP95:st.sloP95}];
  return infl=>{
    if(!(t>0)) return false;
    return ms.every(m=>{
      if(!(+m.sloP95>0)) return true;
      const gen=(m.reasonTok||0)+(m.visibleOut||0);
      const ttft=2*m.resident*st.active/(st.gpuTflops*Math.max(1,st.tp)*st.mfu)*(infl||1);
      return 1.3*((ttft+st.ovh)/1000 + gen/t) <= m.sloP95;
    });
  };
}

function fleetTotals(pools, shared, hw, co){
  const info=RESIL[hw.resil]||RESIL.n;
  const sup=shared.sup;
  // pools co-tenant whole GPUs where memory and bandwidth allow, MIG-sliced
  // pools and supports share partitioned GPUs; ALL of it then packs onto nodes
  const dedicatedG=co? co.count
    : pools.reduce((t,p)=>t+(p.sliced?0:p.d.replicas*p.state.tp),0);
  const sharedG=shared.gpus||0;
  const activeG=dedicatedG+sharedG;
  const servW=Math.max(1, Math.ceil(activeG/hw.perW));
  const servG=servW*hw.perW;
  const spare=servG-activeG;
  // mirrors and DR sites replicate the packed fleet; spares stay shared
  const resilW=info.mult(servW)+info.add;
  const procW=servW+resilW;
  const procG=procW*hw.perW;
  return {servW, servG, activeG, spare, supG:sharedG, supExtraG:0, supNodes:0, resilW, procW, procG,
    kW:procG*hw.g.watts/1000,
    fits:pools.every(p=>p.d.fits),
    sloAll:pools.every(p=>p.perUc.every(x=>x.d.sloAll)),
    agg:pools.reduce((t,p)=>t+p.d.agg,0),
    vramNeed:pools.reduce((t,p)=>t+p.d.total,0)+sup.totalVram,
    vramAvail:pools.reduce((t,p)=>t+p.d.avail,0)+sup.totalVram};
}

/* ================= AUTO-SIZE ================= */
function solvePool(s){
  const weights=s.params*s.bytesW;
  const actGB=Math.min(s.resident+(s.extend?s.reasonTok:0),8192)*s.hidden*12*s.bytesW/1e9;
  const packPct=Math.min(95,Math.max(50,+($('autoUtil')&&$('autoUtil').value)||80)), pack=packPct/100;
  /* The smallest width that holds one copy with cache room. Use the SAME
     inequality compute() enforces - fixed 5 GB plus (gpus-1) x multiGb across
     the group - instead of charging the multi-GPU overhead to every card, which
     was stricter than the engine and bought a width nobody needed. */
  const mgb=(s.multiGb!=null? s.multiGb : 15);
  /* the shared prefix is resident once per replica whether or not any call is
     in flight, so it belongs in the width that must hold one copy */
  const cacheF=Math.min(0.95,Math.max(0,s.cachePct||0));
  const kvTokFit=(()=>{ try{ return compute({...s, gpus:Math.max(1,s.tp||1), tp:Math.max(1,s.tp||1),
    workers:1, batch:1, concurrent:1}).kvTok; }catch(e){ return 0; } })();
  const sharedGB=Math.floor(s.resident*cacheF)*kvTokFit;
  let tp=[1,2,4,8,16,32,64,72].find(t=>weights+actGB+sharedGB+5+(t-1)*mgb <= pack*s.gpuVram*t);
  if(!tp) return {ok:false, packPct,
    reason:`No TP up to 64 fits one copy of ${s.model.name} on ${s.gpu.name}: quantize the weights or pick a higher-VRAM GPU`};
  const tpFit=tp;
  // each member is one request class: its OWN prefill length, its OWN hidden +
  // visible tokens, its OWN targets. A pooled state only blends these for
  // memory and mix decode-step math; constraints must never cross members
  // (a chatbot's P95 must not pay for a reasoning agent's thinking tokens,
  // a translation TTFT must not pay for a legal doc's 131K prefill).
  // Batch is free until memory or bandwidth says otherwise: an arbitrary cap
  // forces ceil(concurrent/cap) replicas, and every extra replica re-reads the
  // whole weight matrix each decode step. Use the same ceiling the user can set
  // by hand and let the fit and SLO loops find the real limit.
  const BATCH_MAX=(FIELDS.inBatch&&FIELDS.inBatch.max)||512;
  const members = (s.members&&s.members.length? s.members
    : [{name:null, conc:s.concurrent, resident:s.resident, visibleOut:s.visibleOut,
        reasonTok:s.reasonTok, extend:s.extend, sloTtft:s.sloTtft, sloTps:s.sloTps, sloP95:s.sloP95}])
    .map(m=>({...m, gen:(m.reasonTok||0)+(m.visibleOut||0)}));
  // prefill skips the member's cached prefix, exactly as the engine does
  const prefillOf=m=>Math.max(0, m.resident - Math.floor(m.resident*Math.min(0.95,Math.max(0,m.cachePct||0))));
  const ttftOf=(m,t,tflops)=>2*prefillOf(m)*s.active/((tflops||s.gpuTflops)*t*s.mfu);
  // widen TP while any member's OWN TTFT target is missed at its OWN prefill
  /* Widen for the first-token targets, but never past the width that meets them
     or past the node's own NVLink island: an unreachable TTFT used to run this
     loop to TP64 and buy 64 cards per replica for a target still missed. */
  { const wall=64;          // crossing nodes for prefill is allowed; it is priced by ic
    let t=tp;
    while(t<wall && members.some(m=>m.sloTtft>0 && ttftOf(m,t)>m.sloTtft)) t*=2;
    // if even the widest allowed group misses every one of them, the target is
    // not a width problem: keep the fitting width and report it as stuck below
    if(t>tp && members.every(m=>!(m.sloTtft>0) || ttftOf(m,t)>m.sloTtft)) t=tp;
    tp=Math.min(72,t); }
  const ttftTp=tp;                 // the width the first-token targets alone needed
  const widened=tp>tpFit;
  const ttftBinder=widened? (members.filter(m=>m.sloTtft>0).sort((a,b)=>ttftOf(b,1)/b.sloTtft-ttftOf(a,1)/a.sloTtft)[0]||{}).name : null;
  const interactive=members.some(m=>m.sloTtft>0||m.sloTps>0||m.sloP95>0);
  // member latency at the pool's mix decode speed: same step rate for every
  // co-batched request, but each member only decodes its own gen tokens
  const memberP95=(m,mixTps,tpAt,tflops)=>1.3*((ttftOf(m,tpAt,tflops)+s.ovh)/1000 + m.gen/Math.max(1e-6,mixTps));
  /* Plan the pool at one tensor-parallel width. Decode is memory-bandwidth
     bound and bandwidth scales with TP, so for a pool that misses a speed or
     P95 target TP is often far cheaper than replicas: adding replicas only
     pushes batch-per-replica toward 1, which asymptotes, while a wider TP
     raises the ceiling itself. We plan at several widths and buy the cheapest
     one that meets every member's targets. */
  function planAt(tp){
    const crossed=tp>s.perW;
    const ic=crossed? Math.min(s.ic,0.7) : s.ic;
    // A pool owns CARDS, not whole nodes. Pools pack onto shared nodes further
    // down, so rounding each pool up to a full node bought GPUs nobody asked
    // for: a pool needing two cards was handed eight.
    const REP_CAP=Math.max(1, Math.floor(64*s.perW/tp));
    const eva=(reps,batch)=>compute({...s, tp, ic, workers:Math.ceil(reps*tp/s.perW),
      gpus:reps*tp, batch});
    let reps, batch, d;
    let converged=false, sloStuck=null, grewForSlo=0, scaleStuck=false, aloneStuck=false;
    const can={};
    if(interactive){
      // fewest replicas that admit the peak concurrency, then grow until it fits
      reps=Math.max(1, Math.ceil(s.concurrent/BATCH_MAX));
      for(;;){
        batch=Math.min(BATCH_MAX,Math.max(1,Math.ceil(s.concurrent/reps)));
        d=eva(reps,batch);
        if(d.total<=pack*d.avail){ converged=true; break; }
        if(reps>=REP_CAP) break;
        reps++;
      }
      if(converged){
        // what a call gets alone at batch 1 on THIS width (the physical best
        // case here): a target that fails even there cannot be met by more
        // replicas, so we never buy nodes for it at this width
        members.forEach(m=>{
          const alone=compute({...s, resident:m.resident, visibleOut:m.visibleOut,
            reasonTok:m.reasonTok, extend:m.extend, sloTtft:m.sloTtft, sloTps:m.sloTps, sloP95:m.sloP95,
            tp, ic, workers:Math.max(1,Math.ceil(tp/s.perW)), gpus:tp, batch:1, concurrent:1});
          can[m.name||'_'] = {tps: !(m.sloTps>0) || alone.slo.tps.pass,
                              p95: !(m.sloP95>0) || alone.slo.p95.pass};
        });
        const stuckList=[];
        members.forEach(m=>{ const c=can[m.name||'_'], tag=m.name?` (${m.name})`:'';
          if(!c.tps) stuckList.push('per-user speed'+tag);
          if(!c.p95) stuckList.push('P95'+tag); });
        // WHICH targets are missed, not just which kinds: a pool mixing a
        // reachable target with an unreachable one of the same kind used to have
        // the hardware that met the reachable one handed straight back
        const missOf=dd=>{ let t=false,p=false; const who=[];
          members.forEach(m=>{ const c=can[m.name||'_'], id=m.name||'_';
            if(c.tps && m.sloTps>0 && dd.tps < m.sloTps){ t=true; who.push(id+'|tps'); }
            if(c.p95 && m.sloP95>0 && memberP95(m, dd.tps, tp) > m.sloP95){ p=true; who.push(id+'|p95'); } });
          return {t, p, set:who.sort().join(',')}; };
        const r0=reps, b0=batch;
        // How many replicas does the binding target actually need? Decode is
        // bwEff / (activeParams x bytesW + batchPerRep x effSeq x kvTok) and
        // batchPerRep is concurrent/replicas, so the answer is closed form.
        // Growing one replica at a time made a 400-iteration guard the real
        // ceiling: the loop fell out of it holding 400 extra replicas, still
        // missing the target, and reported no problem. Solve it instead.
        const batchFor=r=>Math.min(BATCH_MAX,Math.max(1,Math.ceil(s.concurrent/r)));
        d=eva(reps,batch);
        const miss0=missOf(d);
        if(miss0.t||miss0.p){
          // every per-user speed each target implies, in tok/s
          const needs=[];
          members.forEach(m=>{ const c=can[m.name||'_'];
            if(c.tps && m.sloTps>0) needs.push(m.sloTps);
            if(c.p95 && m.sloP95>0 && m.gen>0){
              const room=m.sloP95/1.3-(ttftOf(m,tp)+s.ovh)/1000;
              needs.push(room>0? m.gen/room : Infinity); } });
          // replicas that speed needs: batch per replica is concurrent/replicas,
          // and below one batch no replica count can help
          // decode reads the whole context per step, so the SPEED term keeps effSeq
          const repsFor=T=>{ const bpr=(d.bwEff/T - s.active*s.bytesW)/Math.max(1e-12, d.effSeq*d.kvTok);
            return bpr>=1? Math.max(r0, Math.ceil(s.concurrent/bpr)) : Infinity; };
          // grow to the strictest target the hardware can still reach. One
          // unreachable target must not suppress growth for a reachable one.
          let want=0;
          needs.forEach(T=>{ if(!isFinite(T)) return; const r2=repsFor(T);
            if(r2<=REP_CAP && r2>want) want=r2; });
          if(want>r0){
            reps=want; batch=batchFor(reps); d=eva(reps,batch);
            // rounding safety net only: the closed form lands on the answer, so
            // stop the moment an extra replica stops shrinking the missed set
            // instead of spending the whole allowance on a target it cannot fix
            for(let guard=0; guard<8 && (missOf(d).t||missOf(d).p) && reps<REP_CAP; guard++){
              const before=missOf(d).set;
              const r2=reps+1, b2=batchFor(r2), d2=eva(r2,b2);
              if(missOf(d2).set===before) break;
              reps=r2; batch=b2; d=d2; }
          }
          const miss=missOf(d);
          if(miss.t||miss.p){
            // stuck at SCALE, not alone at batch 1: name it that way downstream
            if(miss.t) stuckList.push('per-user speed'), scaleStuck=true;
            if(miss.p) stuckList.push('P95'), scaleStuck=true;
            // replicas that fixed nothing are pure waste: give them back. The old
            // one-at-a-time loop ran into its 400-iteration guard, kept all 400 and
            // reported no problem at all. The comparison must be the SET of missed
            // targets: growth that met one of them has earned its hardware.
            if(miss.set===miss0.set){ reps=r0; batch=b0; d=eva(reps,batch); }
          }
        }
        // Give back what the targets do not need. Worker granularity can hand a
        // small pool a whole node, and every surplus replica re-reads the full
        // weights each decode step, so shrinking raises utilization AND speed
        // per card. Stop the moment memory or any member's target says no.
        for(let guard=0; guard<400 && reps>1; guard++){
          const r2=reps-1;
          const b2=Math.min(BATCH_MAX,Math.max(1,Math.ceil(s.concurrent/r2)));
          const d2=eva(r2,b2);
          if(d2.total>pack*d2.avail) break;
          if(d2.queued>0) break;                    // must still admit the peak
          const m2=missOf(d2); if(m2.t||m2.p) break;
          reps=r2; batch=b2; d=d2;
        }
        sloStuck = stuckList.length? [...new Set(stuckList)].join(' and ') : null;
        // a target that fails alone at batch 1 can never be met; one that only
        // fails at this concurrency needs more replicas than the fleet allows.
        // Saying "fails even alone at batch 1" about the second is simply false.
        aloneStuck = members.some(m=>{ const c=can[m.name||'_']; return !c.tps || !c.p95; });
        grewForSlo=Math.max(0, reps-r0);
      }
    } else {
      // offline: queueing is fine, so keep hardware minimal and pick the largest batch that fits
      reps=1;
      outer: for(;;){
        for(const b of [512,256,128,64,32,16,8,4,2,1]){
          batch=b; d=eva(reps,b);
          if(d.total<=pack*d.avail){ converged=true; break outer; }
        }
        if(reps>=REP_CAP) break;
        reps++;
      }
    }
    return {tp, crossed, ic, batch, d, converged, sloStuck, grewForSlo, can, scaleStuck, aloneStuck,
      replicas:reps, cards:reps*tp,
      workers:Math.max(1,Math.ceil(reps*tp/s.perW)),
      physGpus: reps*tp};
  }
  // TP candidates: the TTFT-driven width, plus wider ones up to one node's
  // NVLink island (crossing nodes costs interconnect efficiency, so we never
  // widen past perW purely for speed).
  /* Candidate widths. A wider group is not only a speed lever: it also holds a
     bigger batch per replica, so a pool with NO speed target at all can still
     need far fewer cards at TP4 than at TP1. Gating the sweep on speed targets
     gave memory-bound pools an explosion of narrow replicas. */
  const cands=[tp];
  if(interactive||s.concurrent>1) [1,2,4,8,16,32,64,72].forEach(t=>{ if(t>tp&&t<=s.perW) cands.push(t); });
  let plan=null;
  cands.forEach(t=>{ const pl=planAt(t); if(!pl.converged) return;
    const better = !plan
      || (!pl.sloStuck && plan.sloStuck)
      || (!!pl.sloStuck===!!plan.sloStuck && pl.physGpus < plan.physGpus - 1e-9);
    if(better) plan=pl; });
  if(!plan) plan=planAt(tp);
  const tpWide=plan.tp>tp;
  tp=plan.tp;
  const crossed=plan.crossed, ic=plan.ic;
  let workers=plan.workers, batch=plan.batch, d=plan.d;
  const cards=plan.cards;
  const converged=plan.converged, sloStuck=plan.sloStuck, grewForSlo=plan.grewForSlo;
  members.forEach(m=>{ const c=plan.can[m.name||'_']||{}; m.tpsCan=c.tps!==false; m.p95Can=c.p95!==false; });
  const tpsCan=members.every(m=>m.tpsCan), p95Can=members.every(m=>m.p95Can);
  if(!converged) return {ok:false, packPct,
    reason:`Could not fit ${s.model.name} at TP${tp} within the ${packPct}% memory target even at 64 workers: quantize the weights, raise the target, or pick a higher-VRAM GPU`};
  // A dedicated pool costs CARDS since 5.21 (it packs onto shared nodes), so
  // physGpus must be that same number. Pricing it in whole nodes made the sliced
  // branch below beat a plan that was already cheaper: 3 MIG slices "saved"
  // hardware against a single card rounded up to a node of eight.
  const dedicated={ok:true, mode:'dedicated', tp, tpFit, widened, ttftBinder, ttftTp, crossed, workers, cards, batch, packPct, weights, actGB, sloStuck, grewForSlo,
    physGpus: cards};
  // MIG-sliced alternative: TP1 pools whose copy fits a hardware slice can run
  // one replica per slice, sharing physical GPUs with other models/supports
  if(tp===1 && interactive && UC.length>1){
    const profs=sliceProfiles(s.gpu);
    // honest pricing: slices only exist whole, so cost = first-fit-decreasing
    // bins of part.max units. Supports already occupy shared bins; the sliced
    // pool's marginal cost is (bins with pool slices) - (bins with supports alone).
    const binCount=(unitsArr, max)=>{ const bins=[];
      unitsArr.slice().sort((a,b)=>b-a).forEach(u2=>{ const i2=bins.findIndex(x=>x+u2<=max);
        if(i2<0) bins.push(u2); else bins[i2]+=u2; });
      return bins.length; };
    const partS=s.gpu.part||{};
    let supU=[];
    try{ allocSupports({g:s.gpu}).layout.forEach(b=>b.slices.forEach(sl=>{ if(sl.n>0) supU.push(sliceCost(partS, sl.n)); })); }catch(e){}
    const supAlone=supU.length? binCount(supU, binCap(partS)) : 0;
    // why (per largest profile examined) slicing was rejected: surfaced in the
    // auto-size narrative so a half-empty dedicated GPU never looks arbitrary
    let best=null, why=profs.length? null : {t:'nopart'};
    for(const prof of profs){
      if(weights+actGB+1.4 > pack*prof.gb){ why={t:'fit', need:weights+actGB+1.4, cap:pack*prof.gb}; continue; }
      const syn={...s, gpuVram:prof.gb, gpuBw:prof.bw, gpuTflops:prof.tflops, tp:1, perW:1, ic:1, multiGb:1.4};
      // a slice that cannot meet a target the dedicated plan CAN meet is out;
      // targets unachievable on any hardware are ignored here too (parity with
      // the dedicated path). All checks are PER MEMBER with that member's own
      // request shape, never the blended pool shape.
      let rejected=null;
      for(const m of members){
        if(m.sloTtft>0 && ttftOf(m,1,prof.tflops) > m.sloTtft && !(ttftOf(m,tp) > m.sloTtft)){
          rejected={t:'ttft', ms:ttftOf(m,1,prof.tflops), who:m.name}; break; }
        const aloneM=compute({...syn, resident:m.resident, visibleOut:m.visibleOut,
          reasonTok:m.reasonTok, extend:m.extend, sloTtft:m.sloTtft, sloTps:m.sloTps, sloP95:m.sloP95,
          gpus:1, workers:1, batch:1, concurrent:1});
        if(m.sloTps>0 && m.tpsCan!==false && !aloneM.slo.tps.pass){
          rejected={t:'slo', m:'per-user speed'+(m.name?` (${m.name})`:''), have:fmt(aloneM.tps)+' tok/s', want:fmt(m.sloTps)+' tok/s'}; break; }
        if(m.sloP95>0 && m.p95Can!==false && !aloneM.slo.p95.pass){
          rejected={t:'slo', m:'P95 latency'+(m.name?` (${m.name})`:''), have:fmt(aloneM.p95)+' s', want:fmt(m.sloP95)+' s'}; break; }
      }
      if(rejected){ why=rejected; continue; }
      const SLICE_CAP=64;
      let slices=Math.max(1,Math.ceil(s.concurrent/SLICE_CAP)), sb=0, sd=null, okFit=false, stuck=null;
      for(let guard=0; guard<200; guard++){
        sb=Math.min(BATCH_MAX,Math.max(1,Math.ceil(s.concurrent/slices)));
        sd=compute({...syn, gpus:slices, workers:slices, batch:sb});
        if(sd.total<=pack*sd.avail){ okFit=true; break; }
        if(slices>=SLICE_CAP) break;
        slices++;
      }
      if(!okFit){ why={t:'kv'}; continue; }
      const missSlice=dd=>{ let t=false,p=false;
        members.forEach(m=>{
          if(m.tpsCan!==false && m.sloTps>0 && dd.tps < m.sloTps) t=true;
          if(m.p95Can!==false && m.sloP95>0 && memberP95(m, dd.tps, 1, prof.tflops) > m.sloP95) p=true; });
        return {t,p}; };
      for(let guard=0; guard<200; guard++){
        const miss=missSlice(sd);
        if(!(miss.t||miss.p)) break;
        if(sb<=1 || slices>=SLICE_CAP){ stuck=(miss.t?'per-user speed':'')+(miss.t&&miss.p?' and ':'')+(miss.p?'P95':''); break; }
        slices++;
        sb=Math.min(BATCH_MAX,Math.max(1,Math.ceil(s.concurrent/slices)));
        sd=compute({...syn, gpus:slices, workers:slices, batch:sb});
      }
      if(stuck){ why={t:'stuck', stuck}; continue; }
      const packed=binCount([...Array(slices).fill(sliceCost(partS, prof.units)), ...supU], binCap(partS));
      const phys=Math.max(0, packed-supAlone);
      if(!best || phys<best.physGpus) best={ok:true, mode:'sliced', tp:1, sliceU:prof.units, prof,
        workers:slices, batch:sb, packPct, weights, actGB, physGpus:phys, sloStuck:null, grewForSlo:0, widened:false, crossed:false, tpFit:1};
    }
    // pick sliced only when it genuinely saves hardware; targets no hardware can
    // meet are missed identically on both paths and carry over to the report
    if(best){
      best.sloStuck=[...new Set(members.flatMap(m=>[m.tpsCan===false?'per-user speed'+(m.name?` (${m.name})`:''):null,
        m.p95Can===false?'P95'+(m.name?` (${m.name})`:''):null]).filter(Boolean))].join(' and ')||null;
      if(best.physGpus < dedicated.cards - 0.01) return best;
      why={t:'nosave', phys:best.physGpus, ded:dedicated.cards};
    }
    dedicated.sliceWhy =
      !why? null
      : why.t==='nopart'? `${s.gpu.name} has no isolated partitioning (MIG), so each replica keeps a whole GPU`
      : why.t==='fit'? `its ${fmt(why.need)} GB copy does not fit even the largest slice (${fmt(why.cap)} GB usable at the ${packPct}% memory target)`
      : why.t==='slo'? `even alone on the largest usable slice, ${why.m} reaches ${why.have} against the ${why.want} target`
      : why.t==='ttft'? `a slice's reduced compute cannot meet the ${fmt(s.sloTtft)} ms TTFT target (${fmt(why.ms)} ms prefill on the largest usable slice)`
      : why.t==='stuck'? `slices cannot meet the ${why.stuck} target at any replica count`
      : why.t==='kv'? `the KV cache does not fit slice memory at any replica count`
      : why.t==='nosave'? `sharing would not reduce hardware (${fmt(why.phys)} shared-GPU equivalents vs ${why.ded} dedicated GPUs)`
      : null;
  }
  return dedicated;
}

/* Classify by what the use case IS, not by which preset it was started from:
   switching the dropdown to "Custom (manual)" changes nothing about the workload
   but used to drop a voice agent to the reading floor. The preset is only a
   fallback for fields the card does not carry. */
function sloTpsFloor(uc){
  const f=uc.f||{};
  const ci=+f.selCase, c=(ci>=0&&CASES[ci])? CASES[ci] : null;
  const tr=(c&&c.traffic)||{};
  const p95=+f.sloP95||0, reason=+f.inReasonTok||0;
  // a live path: KV pinned for the whole session, or a P95 measured in seconds
  if(f.selPolicy==='all' || (p95>0&&p95<=6) || (tr.direct && c.p95Target>0 && c.p95Target<=6))
    return {tps:30, why:'this is a live path: the token stream has to stay ahead of the conversation'};
  // most tokens hidden and a long budget: total time matters, stream speed does not
  if(reason>0 && (p95>=55 || (!p95 && c && c.p95Target>=55)))
    return {tps:10, why:'most of its tokens are hidden thinking, so total time matters more than stream speed'};
  return {tps:15, why:'a person reads at roughly 15 tok/s'};
}

function sloOverride(p, over){
  const ms=(p.state.members&&p.state.members.length? p.state.members : [{name:null,
    conc:p.state.concurrent, resident:p.state.resident, visibleOut:p.state.visibleOut,
    reasonTok:p.state.reasonTok, extend:p.state.extend, cachePct:p.state.cachePct||0,
    sloTtft:p.state.sloTtft, sloTps:p.state.sloTps, sloP95:p.state.sloP95}])
    .map((m,k)=>{ const o=over[p.members[k]];
      if(!o) return m;
      const mm=Object.assign({}, m, o);
      // the override speaks in UI field ids; the engine wants a fraction
      if(o.inCache!=null) mm.cachePct=Math.min(0.95, Math.max(0, (+o.inCache||0)/100));
      return mm; });
  const nz=v=>{ const n=v.filter(x=>x>0); return n.length? Math.min.apply(null,n) : 0; };
  const conc=ms.reduce((t,m)=>t+(+m.conc||0),0)||1;
  return {members:ms,
    cachePct:ms.reduce((t,m)=>t+(m.cachePct||0)*(+m.conc||0),0)/conc,
    sloTps:Math.max.apply(null, ms.map(m=>+m.sloTps||0).concat([0])),
    sloTtft:nz(ms.map(m=>+m.sloTtft||0)),
    sloP95:nz(ms.map(m=>+m.sloP95||0))};
}

/* What Auto-size would buy for the whole project with these per-use-case targets:
   serving CARDS, and the fleet those cards actually pack into. Quoting cards
   alone was misleading - nodes are bought whole and resilience multiplies them,
   so a real four-card saving can leave the procurement line untouched, and the
   default single-use-case project shows a flat 2x between the two numbers. */
function sloPrice(prj, over){
  const hw=prj.hw;
  let cards=0, stuck=false;
  for(const p of prj.pools){
    let r;
    try{ r=solvePool(poolSolveState(p, hw, sloOverride(p, over))); }
    catch(e){ return null; }
    if(!r||!r.ok) return null;
    if(r.sloStuck) stuck=true;
    cards += (r.cards||r.physGpus||0);
  }
  // a sliced pool's physGpus is already its MARGINAL cost beyond the support
  // GPUs, so the supports' own bins are added exactly once
  let supG=0; try{ supG=allocSupports(hw).gpus||0; }catch(e){}
  const activeG=cards+supG;
  const info=RESIL[hw.resil]||RESIL.n;
  const servW=Math.max(1, Math.ceil(activeG/hw.perW));
  const procW=servW+info.mult(servW)+info.add;
  return {cards:Math.round(cards*100)/100, stuck, activeG,
    servW, procW, procG:procW*hw.perW};
}

function sloOptScan(prj){
  if(!prj||!prj.pools||!prj.pools.length) return [];
  const key=prjSolveSig(prj);
  if(__sloMemo.key===key) return __sloMemo.recs;
  const recs=[];
  try{ recs.push.apply(recs, sloOptBuild(prj)); }catch(e){}
  __sloMemo={key, recs};
  return recs;
}

function sloOptBuild(prj){
  const hw=prj.hw, g=hw.g, out=[];
  const U=Math.min(95,Math.max(50,+($('autoUtil')&&$('autoUtil').value)||80))/100;
  const P95_FACTOR=1.5;   // the most a P95 promise may be relaxed in one suggestion
  const base=sloPrice(prj,{});
  if(!base) return out;
  const secs=x=>fmt(x)+' s';
  // a drop nobody would act on is noise: at least 2 tok/s and at least a tenth
  const worth=(from,to)=>to<from-Math.max(2, 0.1*from);
  /* Per use case: the target that fills U of this card, the floor its own
     workload class refuses to cross, and the two speed targets that follow -
     one that keeps its P95 promise exactly, one that relaxes it by at most half
     again. Both are its own numbers; nothing is blended across use cases. */
  const propOf=(p,x)=>{
    const cur=+x.s.sloTps||0;
    const gen=(+x.s.reasonTok||0)+(+x.s.visibleOut||0);
    const lat=(x.d.ttft+x.s.ovh)/1000;          // first token + framework, seconds
    const p95=+x.s.sloP95||0;
    // a use case with no tok/s target at all can still have its P95 buying the
    // whole pool; returning null here made it invisible to the optimiser
    if(!(cur>0) && !(p95>0)) return null;
    if(p95>0 && p95/1.3-lat<=0) return null;    // its P95 is already impossible
    const minFor=f=>{ if(!(p95>0)||!(gen>0)) return 0;
      const room=f*p95/1.3-lat; return room>0? gen/room : Infinity; };
    const fl=sloTpsFloor(x.uc);
    /* The speed that fills U of the card. A card holds more than it re-reads per
       token: an MoE keeps every expert resident while reading only the active
       ones, and activations plus fixed overhead sit there too. Ignoring that
       residual asked for a target the card could not actually reach (DeepSeek
       671B at TP16: 19.2 tok/s quoted, 23.2 real). */
    const resid=((Math.max(0,x.s.params-x.s.active))*x.s.bytesW + x.d.act)/Math.max(1,p.state.tp)
      + (x.d.fixed+x.d.multi)/Math.max(1, x.d.replicas*Math.max(1,p.state.tp));
    const room=Math.max(1, U*g.vram - resid);
    const atU=(g.bw*1000*p.state.ic*hw.mbu)/room;
    const fill=Math.max(fl.tps, Math.floor(atU));
    const cap=t=>Math.min(cur, Math.max(fill, Math.ceil(t)));
    // round the paired promise the safe way: always a little looser than needed,
    // because writing one the recommended speed cannot meet would be a lie
    const p95For=t=>{ const v=1.3*(lat+gen/t); return v>=10? Math.ceil(v) : Math.ceil(v*10)/10; };
    const relax=cap(minFor(P95_FACTOR));
    // A use case whose P95 already has slack must KEEP that slack: pairing the
    // promise with the new speed unconditionally tightened it, on a button that
    // says "relax".
    /* WHICH promise is actually binding. When the P95 target implies a higher
       per-token speed than sloTps does, the speed target is not the lever at
       all: no reduction of it changes the fleet, and only the P95 can move.
       That case bought 89% of a reported project's cards while the optimiser
       stayed silent, because every proposal it knew how to make was a lower
       sloTps. */
    const p95Needs=minFor(1);                       // tok/s this P95 demands
    const p95Binds=p95>0 && isFinite(p95Needs) && p95Needs>cur+0.5;
    // what the P95 would have to become for the card-filling speed to be legal
    const p95AtFill=p95>0? p95For(Math.max(fl.tps, Math.floor(atU))) : 0;
    return {x, cur, gen, lat, atU, floor:fl, p95, p95For, p95Needs, p95Binds, p95AtFill,
      keep:cap(minFor(1)), relax,
      relaxP95: p95>0? Math.max(p95, p95For(relax)) : 0};
  };
  const applyBtn=(label, sets, msg, primary)=>
    `<button type="button" class="btn-rec no-print${primary?' pri':''}" data-apply="${esc(JSON.stringify({sets, msg}))}">${esc(label)}</button>`;
  const label=pi=>{ if(prj.pools.length<2) return '';
    const t=shortPoolTag(prj.pools,pi);
    const dup=prj.pools.some((q,qj)=>qj!==pi&&shortPoolTag(prj.pools,qj)===t);
    return (dup? `${t} TP${prj.pools[pi].state.tp}` : t)+' · '; };
  // these are counts and targets, not measurements: print 48, not 48.0
  const num=n=>Number.isInteger(+n)? (+n).toLocaleString('en-US') : fmt(n);
  const cards=n=>`${num(n)} card${n===1?'':'s'}`;
  /* Cards are what a suggestion moves; nodes are what you buy. Say both, and say
     plainly when the saving does not reach the procurement line. */
  const outcome=(pr)=>{
    if(!pr) return '';
    const same=pr.procG===base.procG;
    return `<br>Across the whole project, Auto-size buys <b>${cards(base.cards)}</b> at today's targets and <b>${cards(pr.cards)}</b> at these`
      +(same
        ? `, which pack onto the same <b>${base.procW} node${base.procW>1?'s':''} · ${base.procG} GPUs</b>: the saving is headroom on cards you already own, not a smaller order`
        : `: <b>${base.procW} node${base.procW>1?'s':''} · ${base.procG} GPUs</b> procured today versus <b>${pr.procW} node${pr.procW>1?'s':''} · ${pr.procG} GPUs</b>`)
      +`${pr.stuck?', with some targets still out of reach':''}.`;
  };
  const gainOf=pr=>pr.procG<base.procG? `${pr.procG} GPUs` : `${cards(pr.cards)}, same order`;
  const doneOf=(pr,what)=>pr.procG<base.procG
    ? `${what}: ${base.procG} → ${pr.procG} GPUs procured (${cards(base.cards)} → ${cards(pr.cards)})`
    : `${what}: ${cards(base.cards)} → ${cards(pr.cards)}, same ${base.procG}-GPU order`;
  // ---- 1. speed targets, per pool, priced by re-solving the whole project ----
  const rows=[];
  prj.pools.forEach((p,pi)=>{
    const props=p.perUc.map(x=>propOf(p,x)).filter(q=>q&&q.cur>0);
    if(!props.length) return;
    const curMax=Math.max.apply(null, props.map(q=>q.cur));
    const keepSet={}, relaxSet={};
    props.forEach(q=>{ if(q.keep<q.cur-0.5) keepSet[q.x.i]={sloTps:q.keep};
      if(q.relax<q.cur-0.5) relaxSet[q.x.i]={sloTps:q.relax, sloP95:q.p95>0? q.relaxP95 : 0}; });
    const keepMax=Math.max.apply(null, props.map(q=>q.keep));
    const relaxMax=Math.max.apply(null, props.map(q=>q.relax));
    const keepPr=(Object.keys(keepSet).length && worth(curMax,keepMax))? sloPrice(prj,keepSet) : null;
    const relaxPr=(Object.keys(relaxSet).length && worth(curMax,relaxMax))? sloPrice(prj,relaxSet) : null;
    const okp=r=>r && r.cards<base.cards-0.01 && !(r.stuck&&!base.stuck);
    if(!okp(keepPr) && !okp(relaxPr)) return;
    rows.push({p, pi, props, curMax,
      keepSet, relaxSet, keepMax, relaxMax,
      keepPr:okp(keepPr)? keepPr:null, relaxPr:okp(relaxPr)? relaxPr:null});
  });
  rows.sort((a,b)=>Math.min.apply(null,[a.keepPr,a.relaxPr].filter(Boolean).map(r=>r.cards))
                  -Math.min.apply(null,[b.keepPr,b.relaxPr].filter(Boolean).map(r=>r.cards)));
  // the same reasoning applied to every use case in the project, offered once
  const allSet={};
  prj.pools.forEach(p2=>p2.perUc.forEach(x2=>{ const q=propOf(p2,x2);
    if(q&&q.keep<q.cur-0.5) allSet[x2.i]={sloTps:q.keep}; }));
  const allPr=Object.keys(allSet).length>1? sloPrice(prj,allSet) : null;
  let allOffered=false;
  rows.slice(0,3).forEach(row=>{
    const {p, pi, props, curMax}=row;
    const bwCeil=g.bw*1000*p.state.ic*hw.mbu;
    const holds=bwCeil/curMax, ceilPct=Math.min(100, holds/g.vram*100);
    const best=row.keepPr||row.relaxPr;
    const listed=props.filter(q=>q.keep<q.cur-0.5||q.relax<q.cur-0.5)
      .sort((a,b)=>(b.cur-Math.min(b.keep,b.relax))-(a.cur-Math.min(a.keep,a.relax)));
    const lines=listed.slice(0,3).map(q=>{
      const t=row.keepPr? q.keep : q.relax;
      const p95txt=(!row.keepPr&&q.p95>0&&q.relax<q.cur-0.5)
        ? (q.relaxP95>q.p95+1e-9? ` and its P95 promise from ${num(q.p95)} to ${num(q.relaxP95)} s` : ` · its ${num(q.p95)} s P95 promise still holds`)
        : (q.p95>0? ` · its ${num(q.p95)} s P95 promise is untouched`:'');
      const why=(t<=q.floor.tps+0.001&&q.floor.tps>Math.floor(q.atU))? ` · no lower, because ${esc(q.floor.why)}`:'';
      return `<br><b>${esc(ucName(q.x.uc))}</b>: ${num(q.cur)} → <b>${num(t)} tok/s</b>${p95txt}`
        +` · ${fmtTok(q.gen)} tokens stream in ${secs(q.gen/t)} instead of ${secs(q.gen/q.cur)}${why}`;
    }).join('');
    const more=listed.length>3? `<br>…and ${listed.length-3} more use case${listed.length-3>1?'s':''} in this pool.`:'';
    const acts=[];
    // the promise on a button is the number that changes: the order if it moves,
    // otherwise the cards
    const gain=pr=>pr.procG<base.procG? `${pr.procG} GPUs`
      : `${cards(pr.cards)}, same order`;
    const done=pr=>pr.procG<base.procG
      ? `Applied: ${base.procG} → ${pr.procG} GPUs procured (${cards(base.cards)} → ${cards(pr.cards)})`
      : `Applied: ${cards(base.cards)} → ${cards(pr.cards)}, same ${base.procG}-GPU order`;
    if(row.keepPr) acts.push(applyBtn(
      `Apply to ${Object.keys(row.keepSet).length} use case${Object.keys(row.keepSet).length>1?'s':''} → ${gain(row.keepPr)}`,
      row.keepSet, done(row.keepPr), true));
    if(row.relaxPr && (!row.keepPr || row.relaxPr.cards<row.keepPr.cards-0.01)) acts.push(applyBtn(
      `Relax the P95 promises too → ${gain(row.relaxPr)}`,
      row.relaxSet, done(row.relaxPr), !row.keepPr));
    if(!allOffered && allPr && best && allPr.cards<best.cards-0.01){
      acts.push(applyBtn(`Apply to all ${Object.keys(allSet).length} use cases → ${gain(allPr)}`,
        allSet, done(allPr)));
      allOffered=true;
    }
    if(!acts.length) return;
    out.push({lv: best.cards<=base.cards*0.7? 'warn':'ok',
      t:`${label(pi)}The speed target is what this pool is really paying for`,
      b:`Decode reads the weights and the live cache once per token, so a ${num(curMax)} tok/s target lets a ${esc(g.name)} hold only `
        +`<b>${fmt(holds)} GB</b> of its ${fmt(g.vram)} GB (${ceilPct.toFixed(0)}%): the rest is memory the target forbids you to fill. `
        +`Filling ${(U*100).toFixed(0)}% of the card asks for about <b>${fmt(props[0].atU)} tok/s</b>.`
        +lines+more
        +outcome(best),
      acts});
  });
  /* ---- 1b. the P95 promise IS the lever, per pool. A tight P95 on a long
     generation demands a per-token speed far above the stated tok/s target, so
     lowering the speed target changes nothing and the section above has nothing
     to say. Price the P95 itself. ---- */
  prj.pools.forEach((p,pi)=>{
    const props=p.perUc.map(x=>propOf(p,x)).filter(Boolean);
    const bind=props.filter(q=>q.p95Binds);
    if(!bind.length) return;
    // the loosest promise still worth calling a promise: what the card-filling
    // speed would deliver, and a halfway step for the cautious
    const mk=frac=>{ const set={};
      bind.forEach(q=>{ const t=Math.max(q.floor.tps, Math.floor(q.atU));
        const full=q.p95For(t), step=Math.max(q.p95, Math.min(full, q.p95+(full-q.p95)*frac));
        const v=step>=10? Math.ceil(step) : Math.ceil(step*10)/10;
        if(v>q.p95+1e-9) set[q.x.i]={sloP95:v}; });
      return set; };
    const half=mk(0.5), full=mk(1);
    const prHalf=Object.keys(half).length? sloPrice(prj,half) : null;
    const prFull=Object.keys(full).length? sloPrice(prj,full) : null;
    const okp=r=>r && r.cards<base.cards-0.01 && !(r.stuck&&!base.stuck);
    if(!okp(prHalf) && !okp(prFull)) return;
    const bestP=okp(prFull)? prFull : prHalf;
    const acts=[];
    if(okp(prHalf) && (!okp(prFull) || prHalf.cards>prFull.cards+0.01))
      acts.push(applyBtn(`Relax P95 halfway → ${gainOf(prHalf)}`, half,
        doneOf(prHalf,'P95 targets relaxed'), true));
    if(okp(prFull))
      acts.push(applyBtn(`Relax P95 to what fills the card → ${gainOf(prFull)}`, full,
        doneOf(prFull,'P95 targets relaxed'), !acts.length));
    if(!acts.length) return;
    const lines=bind.slice(0,3).map(q=>{
      const t=Math.max(q.floor.tps, Math.floor(q.atU));
      return `<br><b>${esc(ucName(q.x.uc))}</b>: a ${num(q.p95)} s P95 on ${fmtTok(q.gen)} generated tokens demands `
        +`<b>${fmt(q.p95Needs)} tok/s</b> per user`
        +(q.cur>0? `, ${fmt(q.p95Needs/q.cur)}× its own ${num(q.cur)} tok/s target. ` : ` (it has no tok/s target of its own; the P95 is the whole promise). `)
        +`At ${num(t)} tok/s (the speed that fills the card) the same call finishes in about ${fmt(q.p95For(t))} s.`;
    }).join('');
    out.push({lv: bestP.cards<=base.cards*0.7? 'warn':'ok',
      t:`${label(pi)}The P95 promise is what this pool is really paying for, not the speed target`,
      b:`Lowering the tok/s target cannot shrink this pool: its P95 already demands more speed than the target does, so the P95 is the only promise with hardware behind it.`
        +lines+outcome(bestP),
      acts});
  });
  // ---- 2. a first-token target that widened the tensor-parallel group ----
  prj.pools.forEach((p,pi)=>{
    try{
      const r0=solvePool(poolSolveState(p, hw));
      if(!(r0&&r0.ok&&r0.widened&&r0.ttftBinder)) return;
      const x=p.perUc.find(y=>ucName(y.uc)===r0.ttftBinder);
      if(!x||!(+x.s.sloTtft>0)) return;
      const at=2*x.s.resident*x.s.active/(g.tflops*r0.tpFit*hw.mfu);
      const prop=Math.ceil(at/50)*50;
      if(!(prop>+x.s.sloTtft+1)) return;
      const set={}; set[x.i]={sloTtft:prop};
      const pr=sloPrice(prj, set);
      if(!pr||pr.cards>=base.cards-0.01||(pr.stuck&&!base.stuck)) return;
      out.push({lv:'ok', t:`${label(pi)}The first-token target is buying the TP width`,
        b:`<b>${esc(ucName(x.uc))}</b> asks for its first token within ${num(x.s.sloTtft)} ms, and a ${fmtTok(x.s.resident)}-token prefill only makes that at `
          +`TP${r0.tp}; TP${r0.tpFit} is all the model needs to fit. Tensor parallel widens every replica in the pool, so all of it pays for that one target. `
          +`At TP${r0.tpFit} the first token lands in about <b>${fmt(at)} ms</b>. `
          +`Prefix caching, chunked prefill or a disaggregated prefill pool attack the same number without relaxing the promise.`
          +outcome(pr),
        acts:[applyBtn(`Set ${ucName(x.uc)} to ${num(prop)} ms → ${pr.procG<base.procG? pr.procG+' GPUs' : cards(pr.cards)+', same order'}`,
          set, pr.procG<base.procG
            ? `First-token target applied: ${base.procG} → ${pr.procG} GPUs procured`
            : `First-token target applied: ${cards(base.cards)} → ${cards(pr.cards)}, same ${base.procG}-GPU order`, true)]});
    }catch(e){}
  });
  /* ---- 2b. prefix caching. Every serious serving stack computes a repeated
     prefix once (vLLM, SGLang and TensorRT-LLM all ship it), but the studio
     charges a full prefill on every call until the user says how much of the
     sequence actually repeats. Offer it where it would pay, price it honestly,
     and never assume a hit rate on the user's behalf. ---- */
  const cacheCands=[];
  prj.pools.forEach((p,pi)=>{
    try{
      if((p.state.cachePct||0)>0.001) return;               // already modelled
      if(p.perUc.some(x=>(x.s.cachePct||0)>0.001)) return;
      // below 8K a shared prefix is a rounding error; the noise is not worth it
      if(!(p.state.resident>=8192)) return;
      const mk=pct=>{ const o={}; p.perUc.forEach(x=>{ o[x.i]={inCache:pct}; }); return o; };
      /* Rebuild TTFT from the engine's own closed form so the quoted first token
         is the one the page will show, not a hand-waved percentage. If the
         reconstruction cannot reproduce today's number (a sliced pool re-solves
         onto different silicon), quote nothing rather than something plausible. */
      const solveAt=ov=>{ try{ return solvePool(poolSolveState(p, hw, sloOverride(p, ov))); }catch(e){ return null; } };
      const ttftOf=(x,tp,f)=>2*(x.s.resident-Math.floor(x.s.resident*f))*x.s.active
        /(x.s.gpuTflops*Math.max(1,tp)*x.s.mfu);
      const exact=x=>Math.abs(ttftOf(x, x.s.tp, x.s.cachePct||0)-x.d.ttft) <= 0.02*Math.max(1,x.d.ttft);
      const level=pct=>{ const ov=mk(pct), pr=sloPrice(prj, ov), r=solveAt(ov);
        if(!pr) return null;
        if(pr.cards>base.cards+0.01) return null;            // it would cost more
        if(pr.stuck&&!base.stuck) return null;               // it would break a promise
        const tp=(r&&r.ok&&r.mode==='dedicated'&&!p.sliced)? r.tp : 0;
        return {pct, ov, pr, tp,
          saves: pr.cards<base.cards-0.01 || pr.procG<base.procG,
          ttft: tp? x=>(exact(x)? ttftOf(x, tp, pct/100) : null) : ()=>null};
      };
      const lv=[level(30), level(60)].filter(Boolean);
      if(!lv.length) return;
      /* Two ways this is worth saying. Either it buys hardware back, or it buys
         headroom on the first-token promise that is closest to breaking - which
         is the promise that widens TP and buys the hardware in the first place. */
      const tight=p.perUc.filter(x=>+x.s.sloTtft>0)
        .sort((a,b)=>b.d.ttft/b.s.sloTtft - a.d.ttft/a.s.sloTtft)[0];
      const pressure=tight? tight.d.ttft/tight.s.sloTtft : 0;
      if(!lv.some(q=>q.saves) && pressure<0.5) return;
      const best=lv.filter(q=>q.saves).sort((a,b)=>a.pr.cards-b.pr.cards)[0] || lv[lv.length-1];
      cacheCands.push({p, pi, lv, best, tight, pressure,
        gain: base.cards-Math.min.apply(null, lv.map(q=>q.pr.cards))});
    }catch(e){}
  });
  /* One per project, not one per pool. Three pools with the same shared-prefix
     opportunity is one insight repeated, and the recommendation list is capped:
     each repeat evicted something the reader needed more, including the section
     below that explains the whole order. */
  if(cacheCands.length){
    const c=cacheCands.sort((a,b)=>(b.gain-a.gain) || (b.pressure-a.pressure))[0];
    const {p, pi, lv, best, tight}=c;
    const ms=v=>`${num(Math.round(v))} ms`;
    const gain=q=>q.pr.procG<base.procG? `${num(q.pr.procG)} GPUs`
      : q.saves? `${cards(q.pr.cards)}, same order`
      : (tight && q.ttft(tight)!=null)? `first token ${ms(q.ttft(tight))}` : 'headroom, same order';
    const done=q=>q.pr.procG<base.procG
      ? `Shared prefix set to ${q.pct}%: ${base.procG} → ${q.pr.procG} GPUs procured`
      : q.saves? `Shared prefix set to ${q.pct}%: ${cards(base.cards)} → ${cards(q.pr.cards)}, same ${base.procG}-GPU order`
      : `Shared prefix set to ${q.pct}%: same fleet, first-token headroom on the tightest target`;
    const acts=lv.map(q=>applyBtn(`Assume ${q.pct}% shared → ${gain(q)}`, q.ov, done(q), q===best));
    const shown=lv[lv.length-1];
    const ttftLine=(tight && shown.ttft(tight)!=null)
      ? `At ${shown.pct}% shared, <b>${esc(ucName(tight.uc))}</b>'s first token lands near ${ms(shown.ttft(tight))} against its ${ms(tight.s.sloTtft)} target, instead of ${ms(tight.d.ttft)} today. `
      : '';
    const others=cacheCands.length-1;
    out.push({lv:'ok', t:`${label(pi)}A repeated prefix is being prefilled on every call`,
      b:`This pool carries ${fmtTok(p.state.resident)} resident tokens per request and the studio charges a full prefill for every one of them, every call. `
        +`Whatever part of that is byte-identical each time (a system prompt, a tool schema, a few-shot block, a retrieved corpus header) is prefilled once and held once per replica by any server with automatic prefix caching: vLLM, SGLang and TensorRT-LLM all ship it. `
        +ttftLine
        +`Decode is deliberately not discounted here: every call still re-reads its whole context on every token, so this moves first-token time and KV memory and nothing else.`
        +outcome(best.pr)
        +(others>0? `<br>${others} other pool${others>1?'s have':' has'} the same opportunity; the buttons below set this pool, and the same field sits in each use case's Workload station.` : '')
        +`<br><i>Set this only if your serving stack has prefix caching enabled and your prompts really do share that prefix. Measure the hit rate before you buy against it.</i>`,
      acts});
  }
  /* ---- 3. why the fleet is this size, when the cards look empty and nothing
     above had a saving to offer. A half-empty fleet with no explanation reads
     as a bug; the same sloPrice attribution that prices the suggestions can
     price each constraint class instead, so say what the order is buying. */
  try{
    const pools=prj.pools;
    const util=pools.reduce((t,p)=>t+p.d.total,0)/Math.max(1,pools.reduce((t,p)=>t+p.d.avail,0));
    if(util<0.5){
      const allOver=fn=>{ const o={}; prj.pools.forEach(p=>p.perUc.forEach(x=>{ o[x.i]=fn(x); })); return o; };
      const noTtft=sloPrice(prj, allOver(()=>({sloTtft:0})));
      const noSpeed=sloPrice(prj, allOver(()=>({sloTps:0, sloP95:0})));
      const noTps=sloPrice(prj, allOver(()=>({sloTps:0})));
      const noP95=sloPrice(prj, allOver(()=>({sloP95:0})));
      const noAll=sloPrice(prj, allOver(()=>({sloTtft:0, sloTps:0, sloP95:0})));
      if(noAll){
        const dTtft=noTtft? Math.max(0, base.cards-noTtft.cards) : 0;
        const dSpeed=noSpeed? Math.max(0, base.cards-noSpeed.cards) : 0;
        const floorC=noAll.cards;
        const fleet=prj.fleet||{};
        const resilG=Math.max(0,(fleet.procG||0)-(fleet.servG||0));
        const spareG=Math.max(0,(fleet.servG||0)-(fleet.activeG||0));
        const lines=[];
        if(dSpeed>0.01){
          // only say a relaxation does not exist after PRICING the loosest one
          const offered=out.some(r=>/speed target|P95 promise/.test(r.t));
          let why='';
          if(!offered){
            const loose={}; prj.pools.forEach(p2=>p2.perUc.forEach(x=>{
              const q=propOf(p2,x); if(!q) return;
              const t=Math.max(q.floor.tps, Math.floor(q.atU));
              loose[x.i]={sloTps:Math.min(q.cur,t), sloP95:q.p95>0? Math.max(q.p95, q.p95For(t)) : 0}; }));
            const pr=Object.keys(loose).length? sloPrice(prj, loose) : null;
            why = (pr && pr.cards<base.cards-0.01)
              ? ` (a looser set would reach ${cards(pr.cards)}, but not by a change this tool is willing to propose on its own: relax the promises yourself in the Workload station)`
              : ` (priced: even at the loosest targets their workload class allows, the fleet does not shrink, so the promises are not what is buying these cards)`;
          }
          const dP95=noP95? Math.max(0, base.cards-noP95.cards) : 0;
          const dTps=noTps? Math.max(0, base.cards-noTps.cards) : 0;
          // name the promise that owns them: they need different levers
          if(dP95>0.01 && dP95>=dTps) lines.push(`<br>· <b>${cards(dP95)}</b> exist only to keep the <b>P95 promises</b>`+why);
          else if(dTps>0.01 && dTps>dP95) lines.push(`<br>· <b>${cards(dTps)}</b> exist only to keep the <b>per-user stream speed</b> targets`+why);
          else lines.push(`<br>· <b>${cards(dSpeed)}</b> exist only to keep the per-user speed and P95 promises together (neither alone accounts for them)`+why);
        }
        if(dTtft>0.01) lines.push(`<br>· <b>${cards(dTtft)}</b> exist only to keep the first-token promises`);
        lines.push(`<br>· <b>${cards(floorC)}</b> is the floor with every target off: what admitting ${pools.reduce((t,p)=>t+p.state.concurrent,0)} concurrent calls and holding their KV takes on this hardware`);
        if(spareG>0) lines.push(`<br>· <b>${spareG} GPU slot${spareG>1?'s':''}</b> ${spareG>1?'are':'is'} node-rounding: nodes are bought whole (${hw.perW}/node)`);
        if(resilG>0) lines.push(`<br>· <b>${resilG} GPUs</b> are the resilience pattern (${esc((RESIL[hw.resil]||RESIL.n).long)}), idle until a failure`);
        out.push({lv:'ok', t:`Why the fleet is this size when the cards sit at ${(util*100).toFixed(0)}%`,
          b:`Memory is not what this project is paying for. Of the <b>${fleet.procW||'?'} node${(fleet.procW||2)>1?'s':''} · ${fleet.procG||'?'} GPUs</b> on the order:`
            +lines.join('')
            +`<br>A card can be nearly empty in memory and still fully busy: decode is bound by memory bandwidth and prefill by compute, so fleets sized for latency promises or peak admission leave VRAM unused by design. The levers that shrink this order are the ones priced above${out.length? '' : ': relax a promise, reduce peak concurrency or resident context, quantize the KV cache, or pick a leaner resilience pattern'}.`,
          acts:[]});
      }
    }
  }catch(e){}
  /* Six, not five: the prefix-cache class was added after this cap and its one
     entry silently evicted "why the fleet is this size" on both reference
     projects - the very explanation a reader with a half-empty fleet needs. */
  return out.slice(0,6);
}

function shortPoolTag(pools, pi){
  const words=pools.map(p=>p.state.model.name.split(/\s+/));
  const w=words[pi]; let s=0;
  while(s<w.length-1 && words.some((o,oi)=>oi!==pi && o[s]===w[s])) s++;
  return w[s]||w[0];
}

function gpuFitScan(prj){
  if(!prj||!prj.pools||!prj.pools.length) return null;
  const key=prjSolveSig(prj);
  if(__fitMemo.key===key) return __fitMemo.rows;
  const rows=[];
  GPUS.forEach(g=>{
    if(!/Data Center/.test(g.cls||'')) return;
    let cards=0, ok=true, stuck=false;
    for(const p of prj.pools){
      let r;
      try{ r=solvePool(poolSolveState(p, prj.hw, {gpu:g, gpuVram:g.vram, gpuBw:g.bw, gpuTflops:g.tflops})); }
      catch(e){ ok=false; break; }
      if(!r||!r.ok){ ok=false; break; }
      if(r.sloStuck) stuck=true;
      cards += (r.cards||r.physGpus||0);
    }
    if(!ok||!cards) return;
    rows.push({g, cards, kW:+(cards*g.watts/1000).toFixed(1), stuck});
  });
  rows.sort((a,b)=>a.cards-b.cards || a.kW-b.kW);
  __fitMemo={key, rows};
  return rows;
}

function buildRecs(s,d,m,g,prelaunch){
  const recs=[]; const util=d.avail>0? d.total/d.avail : 1;
  /* An action is offered only where clicking it does exactly what the sentence
     says. kind 'lever' writes a manual control (TP, batch, workers) and only
     makes sense where the solver is not about to overwrite it; kind 'safe'
     changes an input the solver honours (a target, a precision, resilience). */
  const push=(lv,t,b,acts)=>recs.push({lv,t,b,acts});
  const qFp8=QUANTS.findIndex(q=>q.name==='FP8');
  const kFp8=KV_QUANTS.findIndex(q=>q.name==='FP8');
  let bottleneck='none';
  if(!d.fits) bottleneck='VRAM capacity';
  else if(d.slo.ttft.on&&!d.slo.ttft.pass) bottleneck='prefill compute (TTFT)';
  else if(d.slo.tps.on&&!d.slo.tps.pass) bottleneck='decode bandwidth';
  else if(d.slo.p95.on&&!d.slo.p95.pass) bottleneck='generation length vs P95 target';
  else if(d.queued>0) bottleneck='admission (batch × replicas)';
  else if(util>0.92) bottleneck='VRAM headroom';

  const perRepCap=s.tp*s.gpuVram, perRepNeed=d.weights+d.act;
  if(perRepNeed>perRepCap){
    const minTp=Math.ceil(perRepNeed/s.gpuVram);
    const fitQ=QUANTS.filter(q=>q.bytes<s.bytesW && (s.params*q.bytes+d.act)<perRepCap).sort((a,b)=>b.bytes-a.bytes)[0];
    const holdActs=[{label:`Set tensor parallel to ${minTp}`, fields:{inTp:minTp}, kind:'lever'}];
    if(fitQ) holdActs.push({label:`Switch weights to ${fitQ.name}`, fields:{selWQuant:QUANTS.indexOf(fitQ)}, kind:'safe'});
    push('crit','One replica cannot hold the model',
      `The model is distributed over TP GPUs, and GPUs beyond TP hold extra copies, not extra room. Each TP${s.tp} slice group spans ${fmt(perRepCap)} GB of VRAM but one copy of ${m.name} needs ${fmt(perRepNeed)} GB, so every group overflows identically and adding workers cannot help. Fix it with the Tensor parallel slider: TP ${minTp} or more fits one copy${minTp>s.perW?` (beyond the ${s.perW}-GPU NVLink island: raise GPUs per worker to model rack-scale parts, or set interconnect efficiency 0.6 to 0.7 for the cross-node hop; real systems use pipeline parallelism here, which this tool does not model)`:''}; TP ${s.gpus} distributes a single copy across the whole fleet. Alternatives: ${fitQ?`${fitQ.name} weights (${fmt(s.params*fitQ.bytes)} GB fits at TP${s.tp}), `:''}a higher-VRAM GPU, or a smaller model.`, holdActs);
  }
  if(!d.fits){
    const overBy=d.total-d.avail, addW=Math.max(1,Math.ceil(overBy/(s.perW*s.gpuVram)));
    let opts=[];
    if(perRepNeed<=perRepCap) opts.push(`add ≈${addW} worker${addW>1?'s':''}`);
    if(s.bytesW>1) opts.push(`FP8 weights (saves ${fmt(d.weightsAll/2)} GB)`);
    if(s.bytesK>1) opts.push(`FP8 KV cache (saves ${fmt(d.kvTotal/2)} GB)`);
    opts.push('trim resident context or batch');
    const fitActs=[];
    if(perRepNeed<=perRepCap) fitActs.push({label:`Add ${addW} worker${addW>1?'s':''}`, fields:{inWorkers:s.workers+addW}, kind:'lever'});
    if(s.bytesW>1&&qFp8>=0) fitActs.push({label:'Switch weights to FP8', fields:{selWQuant:qFp8}, kind:'safe'});
    if(s.bytesK>1&&kFp8>=0) fitActs.push({label:'Switch KV cache to FP8', fields:{selKQuant:kFp8}, kind:'safe'});
    push('crit','Configuration does not fit',`Needs ${fmt(d.total)} GB against ${fmt(d.avail)} GB of serving VRAM, over by ${fmt(overBy)} GB${d.replicas>1?` (${d.replicas} replicas × ${fmt(d.weights)} GB weights each)`:''}. Options: ${opts.join(', ')}.`, fitActs);
  }
  if(d.effSeq>m.ctx)
    push('crit','Context exceeds the model',`Resident + reasoning is ${fmtTok(d.effSeq)} but ${m.name} tops out at ${fmtTok(m.ctx)}. Reduce resident tokens${s.extend&&s.reasonTok?', disable KV extension,':''} or pick a longer-context model.`);
  if(s.tp>s.perW){
    if(s.ic>0.75)
      push('crit','Tensor parallel crosses node boundaries',`TP${s.tp} with ${s.perW} GPU per worker forces TP traffic over the network. Lower TP to ${s.perW} or less, raise GPUs per worker, or model the penalty with interconnect efficiency 0.6 to 0.7.`);
    else
      push('ok','TP crosses nodes (penalty modeled)',`TP${s.tp} spans ${Math.ceil(s.tp/s.perW)} workers and interconnect efficiency ${s.ic} models the cross-node cost on decode. Prefill is still estimated optimistically; production systems usually run TP${s.perW} inside the node with pipeline parallelism across nodes, or rack-scale NVLink parts.`);
  }
  if(d.fits&&d.slo.ttft.on&&!d.slo.ttft.pass){
    const tp2=Math.min(s.tp*2,s.gpus), t2=d.ttft*s.tp/tp2;
    push('warn','TTFT misses its target',`Prefill takes ${fmt(d.ttft)} ms against a ${fmt(s.sloTtft)} ms target. TP ${s.tp} to ${tp2} lands ≈${fmt(t2)} ms${tp2>s.perW?' (but crosses nodes)':''}; prefix caching, chunked prefill or a disaggregated prefill pool attack the same problem without more GPUs.`,
      tp2>s.tp? [{label:`Widen to TP ${tp2} (≈${fmt(t2)} ms)`, fields:{inTp:tp2}, kind:'lever'}] : []);
  }
  if(d.fits&&d.slo.tps.on&&!d.slo.tps.pass){
    const halfB=Math.max(1,Math.floor(d.batchPerRep/2));
    const t2=d.bwEff/(s.active*s.bytesW+halfB*d.effSeq*d.kvTok);
    { // under the 'all sessions stay in KV' policy the engine admits everyone
      // regardless of batch, so the batch lever is a no-op: the honest lever
      // there is more replicas, which is what halves batch-per-replica
      const pinned=s.policy==='all';
      const w2=Math.ceil(d.replicas*2*s.tp/s.perW);
      push('warn','Per-user speed misses its target',`${fmt(d.tps)} tok/s against a ${fmt(s.sloTps)} tok/s target. ${pinned
        ? `Every session is pinned in KV, so batch cannot turn calls away: doubling replicas to ${d.replicas*2} (${w2} workers) gives ≈${fmt(t2)} tok/s`
        : `Halving batch per replica to ${halfB} gives ≈${fmt(t2)} tok/s at lower aggregate`}; FP8 KV, a higher-bandwidth GPU, or speculative decoding (1.5 to 3x) are the structural fixes.`,
      [pinned? {label:`Double replicas (${w2} workers, ≈${fmt(t2)} tok/s)`, fields:{inWorkers:w2}, kind:'lever'}
             : {label:`Halve batch to ${halfB} (≈${fmt(t2)} tok/s)`, fields:{inBatch:halfB}, kind:'lever'}]
        .concat(s.bytesK>1&&kFp8>=0? [{label:'Switch KV cache to FP8', fields:{selKQuant:kFp8}, kind:'safe'}] : [])); }
  }
  if(d.fits&&d.slo.p95.on&&!d.slo.p95.pass){
    const tpsMax=d.bwEff/(s.active*s.bytesW+d.effSeq*d.kvTok);
    const minLat=((d.ttft+s.ovh)/1000+d.genTok/tpsMax)*1.3;
    if(minLat>s.sloP95)
      { const pv=minLat>=10? Math.ceil(minLat) : Math.ceil(minLat*10)/10;
      push('crit','P95 target is unachievable for this workload',`Each call generates ${fmtTok(d.genTok)} tokens (${fmtTok(s.reasonTok)} reasoning + ${fmtTok(s.visibleOut)} visible). Even alone on this hardware at batch 1, that takes ≈${fmt(minLat)} s at P95 against a ${fmt(s.sloP95)} s target. No amount of GPUs fixes this: cut reasoning or visible tokens, turn reasoning off for this use case, or relax the P95 target.`,
        [{label:`Relax P95 to ${fmt(pv)} s (the floor this workload can meet)`, fields:{sloP95:pv}, kind:'safe'}]
          .concat(s.reasonTok>0? [{label:'Turn reasoning off', fields:{selReason:'None'}, kind:'safe'}] : [])); }
    else {
      const tpsNeeded=d.genTok/(s.sloP95/1.3-(d.ttft+s.ovh)/1000);
      const bNeeded=Math.max(1,Math.floor((d.bwEff/tpsNeeded-s.active*s.bytesW)/(d.effSeq*d.kvTok)));  // speed term: full context
      push('warn','P95 latency misses its target',`P95 is ${fmt(d.p95)} s against ${fmt(s.sloP95)} s. Reaching ≈${fmt(tpsNeeded)} tok/s per user would meet it: lower max batch per replica to ≈${bNeeded} (fewer calls admitted per copy), or add speculative decoding (1.5 to 3x decode speed).`,
        s.policy==='all'? [] : [{label:`Cap batch at ${bNeeded}`, fields:{inBatch:bNeeded}, kind:'lever'}]);
    }
  }
  if(d.queued>0&&d.fits){
    const batchNeeded=Math.ceil(s.concurrent/d.replicas);
    const canBatch=batchNeeded<=Math.min(d.maxBatchMem||0,512);
    const needW=Math.ceil(Math.max(1,Math.ceil(s.concurrent/s.batch))*s.tp/s.perW);
    push('warn','Calls queue at peak',`${d.queued} of ${s.concurrent} concurrent calls wait; only ${d.active} are admitted. ${canBatch
      ? `Raising max batch per replica from ${s.batch} to ${batchNeeded} admits everyone (memory allows up to ${fmt(Math.min(d.maxBatchMem,512))}).`
      : `At batch ${s.batch}, admitting everyone needs ≈${needW} workers (currently ${s.workers}); or raise the batch and accept slower per-user speed.`}`,
      [canBatch? {label:`Raise batch to ${batchNeeded}`, fields:{inBatch:batchNeeded}, kind:'lever'}
               : {label:`Set ${needW} workers`, fields:{inWorkers:needW}, kind:'lever'}]);
  }
  if(d.fits&&util>0.92)
    push('warn','Headroom is thin',`${(util*100).toFixed(0)}% of serving VRAM is committed. Growth, longer contexts or a library update can tip this over; one more worker or FP8 KV restores margin.`,
      [{label:'Add one worker', fields:{inWorkers:s.workers+1}, kind:'lever'}]
        .concat(s.bytesK>1&&kFp8>=0? [{label:'Switch KV cache to FP8', fields:{selKQuant:kFp8}, kind:'safe'}] : []));
  if(d.kvTotal>d.weightsAll)
    push('warn','KV-dominated deployment',`Cache (${fmt(d.kvTotal)} GB) outweighs weights (${fmt(d.weightsAll)} GB). FP8 or INT4 KV, compressed-KV models (MLA), or shorter resident sequences pay off most here.`,
      s.bytesK>1&&kFp8>=0? [{label:`Switch KV cache to FP8 (saves ${fmt(d.kvTotal/2)} GB)`, fields:{selKQuant:kFp8}, kind:'safe'}] : []);
  if(s.resil==='n'&&s.workers>1)
    push('warn','No redundancy configured',`A single worker failure removes ${fmt(100/s.workers)}% of capacity with nothing to absorb it. N+1 costs one worker (${s.perW} GPUs, ${fmt(s.perW*g.watts/1000)} kW) and removes that cliff.`,
      [{label:'Switch to N+1', global:{selResil:'n1'}, kind:'safe'}]);
  if(prelaunch)
    push('warn','Pre-launch GPU selected',`${g.name} is announced but not shipping; specs are estimates. Re-validate against datasheets before committing a proposal.`);
  const arch=g.arch||'';
  if(s.wq.name==='NV FP4' && !/Blackwell|Rubin/i.test(arch))
    push('warn','NVFP4 needs Blackwell-class hardware',`${g.name} (${arch}) has no native FP4 tensor path. NVFP4 weights would run through software dequantization: the memory savings hold, most of the speed benefit does not. Pick FP8 here, or a Blackwell/Rubin part for FP4.`);
  if(s.wq.name==='FP8' && /Ampere|Apple|Gaudi 2/i.test(arch))
    push('warn','FP8 is not native on this GPU',`${arch} predates hardware FP8 tensor cores. FP8 weights run via software paths (weight-only W8A16 at best): capacity math holds, the compute and bandwidth gains largely do not. Budget with BF16 speeds on ${g.name}, or choose a Hopper-class or newer part.`);
  if(s.wq.name==='MXFP4' && !/Blackwell|Rubin/i.test(arch))
    push('ok','MXFP4 runs in software here',`MXFP4 is native on Blackwell-class parts; on ${arch} it executes via software kernels (as GPT-OSS does on Hopper). Memory savings are real; expect less of the throughput gain.`);
  if(/Unified/i.test(g.mem))
    push('warn','Unified-memory hardware',`Capacity is generous but ${fmt(g.bw)} TB/s of bandwidth caps decode speed. Fine for development or single-user work, not for concurrent serving.`);
  // a latency-bound pool is not over-provisioned: its cards are bought by a
  // promise, and telling the user to shrink it contradicts the solver
  const latencyBound=(s.sloTps>0&&d.slo.tps.pass)||(s.sloP95>0&&d.slo.p95.pass)||(s.sloTtft>0&&d.slo.ttft.pass);
  if(d.fits&&util<0.35&&d.queued===0&&s.gpus>1&&!latencyBound)
    push('ok','Likely over-provisioned',`Only ${(util*100).toFixed(0)}% of serving VRAM is used and every call is admitted. Fewer workers, a smaller TP, or a cheaper part could carry this load; alternatively raise batch and serve more traffic on the same metal.`,
      [{label:'Run Auto-size', solve:true, kind:'safe'}]);
  if(!recs.some(r=>r.lv!=='ok')&&d.fits&&d.sloAll)
    push('ok','Balanced configuration',`Fits with ${fmt(d.headroom)} GB headroom (${(util*100).toFixed(0)}% used), all enabled SLOs pass, and every call is admitted at peak. Nothing here is broken; any further saving has to come from the promises themselves.`);
  const rank={crit:0,warn:1,ok:2};
  recs.sort((a,b)=>rank[a.lv]-rank[b.lv]);
  return {bottleneck, recs:recs.slice(0,7)};
}

/* ================= READABLE SHARE LINKS  #p=t:  =================
   A normal share link carries the whole project as deflate + base64, which no
   assistant can produce in a chat window: it cannot compress, and it cannot
   base64 a kilobyte of JSON reliably. This form is plain text, so ChatGPT,
   Gemini, Claude and anything else can write a working link straight into an
   answer, and a person can read and edit it afterwards.

     #p=t:gpu=H200 141GB NVL;perw=8;resil=n1;uc=Support chat;model=Llama 3.3 70B;
          quant=FP8;preset=Simple RAG;users=2000

   Pairs are separated by ";", each is key=value, and every "uc=" starts a new
   use case (keys before the first one are project-wide). It describes the
   WORKLOAD only: the studio solves TP, replicas and batch on import, exactly as
   it does for a compressed link, so there is nothing here a caller can get
   wrong about the hardware. */
function tsDec(v){ let x=String(v==null?'':v).replace(/\+/g,' ');
  try{ x=decodeURIComponent(x); }catch(e){}
  return x.trim(); }

function tsBool(v){ const x=tsDec(v).toLowerCase();
  return !(x==='0'||x==='no'||x==='false'||x==='off'); }

/* Forgiving on purpose: an assistant writing "h200" or "llama-3.3-70b" from
   memory should land on the library entry, and an ambiguous shorthand should
   say so rather than silently size the wrong thing. */
function tsPick(names, q, notes, what){
  const norm=x=>String(x).toLowerCase().replace(/[^a-z0-9.]+/g,'');
  const n=norm(q); if(!n) return -1;
  const idx=names.map((x,i)=>[norm(x),i]);
  let hits=idx.filter(h=>h[0]===n);
  if(!hits.length) hits=idx.filter(h=>h[0].startsWith(n));
  if(!hits.length) hits=idx.filter(h=>h[0].includes(n));
  if(!hits.length) return -1;
  if(hits.length>1) notes.push(`"${q}" matches ${hits.length} ${what} entries; used "${names[hits[0][1]]}"`);
  return hits[0][1];
}

function parseTextShare(text){
  const notes=[], unknown=[];
  const cards=[]; let g={}, cur=null;
  String(text).split(';').forEach(part=>{
    if(!part.trim()) return;
    const eq=part.indexOf('=');
    if(eq<0){ unknown.push(part.trim()); return; }
    const k=tsDec(part.slice(0,eq)).toLowerCase(), v=part.slice(eq+1);
    if(k==='uc'||k==='usecase'||k==='use-case'){ cur={name:tsDec(v)}; cards.push(cur); return; }
    (cur||g)[k]=v;
  });
  if(!cards.length){ // a single-use-case link may skip "uc=" entirely
    cur={name:''}; cards.push(cur);
    Object.keys(g).forEach(k=>{ if(!TS_PROJECT[k]){ cur[k]=g[k]; delete g[k]; } });
  }
  // ---- project level
  const gi=g.gpu!=null? tsPick(GPUS.map(x=>x.name), tsDec(g.gpu), notes, 'GPU') : -1;
  if(g.gpu!=null && gi<0) return {error:`GPU "${tsDec(g.gpu)}" is not in the library. Names are listed in docs/URL-FORMAT.md.`};
  const num=(v,d)=>{ const n=+tsDec(v); return isFinite(n)? n : d; };
  const cfg={ hardware:{}, tuning:{} };
  if(gi>=0) cfg.gpu=GPUS[gi].name;
  if(g.perw!=null) cfg.hardware.gpusPerWorker=num(g.perw, 8);
  if(g.resil!=null){ const r=tsDec(g.resil).toLowerCase();
    if(RESIL[r]) cfg.hardware.resilience=r;
    else notes.push(`resilience "${tsDec(g.resil)}" is not a pattern; kept the current one`); }
  if(g.mfu!=null) cfg.tuning.prefillMFU=num(g.mfu);
  if(g.mbu!=null) cfg.tuning.decodeMBU=num(g.mbu);
  if(g.ic!=null) cfg.tuning.interconnectEff=num(g.ic);
  if(g.ovh!=null) cfg.tuning.frameworkOverheadMs=num(g.ovh);
  if(g.util!=null) cfg.tuning.autoSizeUtilPct=num(g.util);
  Object.keys(g).forEach(k=>{ if(!TS_PROJECT[k]) unknown.push(k); });
  // ---- use cases
  const usecases=[];
  for(let i=0;i<cards.length;i++){
    const c=cards[i], out={};
    Object.keys(c).forEach(k=>{ if(k!=='name' && !TS_CARD[k]) unknown.push(k); });
    // preset first: it supplies every workload field the link does not state
    let ci=-1;
    if(c.preset!=null){
      ci=tsPick(CASES.map(x=>x.name), tsDec(c.preset), notes, 'workload preset');
      if(ci<0) notes.push(`workload preset "${tsDec(c.preset)}" is not in the library; used explicit values only`);
    }
    const cs=ci>=0? CASES[ci] : null;
    // model
    let model=null;
    const mv=c.model!=null? tsDec(c.model) : '';
    if(/^custom:/i.test(mv)){
      const n2=mv.slice(7).split('/').map(x=>+x);
      if(n2.length<7 || n2.some(x=>!isFinite(x)||x<=0))
        return {error:`custom model on "${c.name||'use case '+(i+1)}" needs params/active/hidden/layers/kvHeads/headDim/ctx`};
      model={custom:true, params:n2[0], active:n2[1], hidden:n2[2], layers:n2[3], kvHeads:n2[4], headDim:n2[5], ctx:n2[6]};
    } else if(mv){
      const mi=tsPick(MODELS.map(x=>x.name), mv, notes, 'model');
      if(mi<0) return {error:`model "${mv}" is not in the library. Use one of the ${MODELS.length} names in docs/URL-FORMAT.md, or model=custom:params/active/hidden/layers/kvHeads/headDim/ctx.`};
      model={custom:false, name:MODELS[mi].name};
    } else return {error:`use case ${i+1} has no model. Every "uc=" needs a model=.`};
    out.model=model;
    const qi=c.quant!=null? tsPick(QUANTS.map(x=>x.name), tsDec(c.quant), notes, 'weight quantization') : -1;
    if(c.quant!=null && qi<0) notes.push(`weight quantization "${tsDec(c.quant)}" not found; used FP8`);
    out.weightQuant=qi>=0? QUANTS[qi].name : 'FP8';
    const ki=c.kv!=null? tsPick(KV_QUANTS.map(x=>x.name), tsDec(c.kv), notes, 'KV quantization') : -1;
    if(c.kv!=null && ki<0) notes.push(`KV quantization "${tsDec(c.kv)}" not found; used FP8`);
    out.kvQuant=ki>=0? KV_QUANTS[ki].name : 'FP8';
    out.preset=cs? cs.name : null;
    out.residentSeq = c.seq!=null? num(c.seq, 4096) : (cs&&cs.resident? cs.resident : 4096);
    out.visibleOut  = c.out!=null? num(c.out, 400)  : (cs&&cs.visibleOut? cs.visibleOut : 400);
    out.sharedPrefixPct = c.cache!=null? Math.min(95, Math.max(0, num(c.cache, 0))) : (cs&&cs.cachePct? cs.cachePct : 0);
    // reasoning: a number is an exact budget, a word is one of the classes
    let rz;
    if(c.reason!=null){
      const rv=tsDec(c.reason), rn=+rv;
      if(isFinite(rn)) rz = rn>0? {mode:'Custom', tokens:rn} : {mode:'None', tokens:0};
      else { const key=Object.keys(REASON_TOK).find(x=>x.toLowerCase().startsWith(rv.toLowerCase().slice(0,5)));
        if(key) rz={mode:key, tokens:REASON_TOK[key]};
        else { notes.push(`reasoning "${rv}" is not a class or a token count; used None`); rz={mode:'None', tokens:0}; } }
    } else if(cs) rz = cs.reasonTok? {mode:'Custom', tokens:cs.reasonTok} : {mode:cs.reasoning||'None', tokens:REASON_TOK[cs.reasoning]||0};
    else rz={mode:'None', tokens:0};
    rz.extendsKV = c.extend!=null? tsBool(c.extend) : true;
    out.reasoning=rz;
    out.kvPolicy = c.policy!=null
      ? (/^(all|session|pinned)/i.test(tsDec(c.policy))? 'all' : 'running')
      : (cs&&cs.policy==='all'? 'all' : 'running');
    const slo={ttftMs:0, tps:0, p95s:0};
    slo.ttftMs = c.ttft!=null? num(c.ttft, 0) : (cs? cs.ttftTarget||0 : 0);
    slo.tps    = c.tps !=null? num(c.tps, 0)  : (cs? cs.tpsTarget ||0 : 0);
    slo.p95s   = c.p95 !=null? num(c.p95, 0)  : (cs? cs.p95Target ||0 : 0);
    out.sloTargets=slo;
    if(c.batch!=null) out.maxBatchPerReplica=num(c.batch, 64);
    /* Conversation length. Stating callmin alone is enough: the rate and the base
       come from the preset's own session shape, so `callmin=12` means "the same
       workload, but calls run twelve minutes". */
    const shp = cs&&cs.session? cs.session : null;
    const saidSession = c.callmin!=null || c.tokmin!=null || c.prompt!=null || c.basis!=null;
    if(saidSession || shp){
      const mins = c.callmin!=null? Math.min(240, Math.max(0, num(c.callmin, 0))) : (shp? shp.min : 0);
      const rate = c.tokmin !=null? Math.min(20000, Math.max(0, num(c.tokmin, 0))) : (shp? shp.tokMin : 200);
      const base = c.prompt !=null? Math.max(0, num(c.prompt, 0)) : (shp? shp.base : Math.max(0,(out.residentSeq||4096)-1000));
      const basis= c.basis  !=null && /^(mean|avg)/i.test(tsDec(c.basis))? 'mean' : 'peak';
      out.session={callMinutes:mins, tokensPerMinute:rate, baseTokens:base, basis};
      /* Only an EXPLICIT statement about the call moves the resident sequence.
         A link that just names a preset keeps that preset's own resident figure
         to the token, even though the shape would reproduce it to within 0.1%. */
      if(saidSession && c.seq==null && mins>0 && rate>0)
        out.residentSeq = Math.round(base + rate*mins/(basis==='mean'?2:1));
    }
    // concurrency: an explicit count wins and is marked manual, otherwise the
    // people-at-peak number drives the estimator the same way Normal mode does
    const users = c.users!=null? Math.max(1, Math.round(num(c.users, 0))) : null;
    const conc  = c.conc !=null? Math.max(1, Math.round(num(c.conc,  0))) : null;
    if(conc!=null) out.concurrentCalls=conc;
    const est={};
    if(c.turns!=null) est.turnsPerHour=num(c.turns);
    if(c.calls!=null) est.callsPerTurn=num(c.calls);
    if(c.burst!=null) est.burst=num(c.burst);
    if(c.dur!=null)   est.callDurS=num(c.dur);
    if(users!=null) est.sessions=users;
    if(Object.keys(est).length) out.estimator=est;
    // supports: named kinds, "none" to strip them, otherwise the preset's own
    let sup;
    if(c.supports!=null){
      const raw=tsDec(c.supports).toLowerCase();
      if(!raw||raw==='none'||raw==='-') sup=[];
      else sup=raw.split(',').map(x=>x.trim()).filter(Boolean).map(k=>{
        const kk=TS_SUP.find(x=>x.startsWith(k.slice(0,3)));
        if(!kk){ notes.push(`support kind "${k}" is not one of ${TS_SUP.join(', ')}`); return null; }
        const d=SUP_DEFAULT(kk); return d? {kind:kk, model:d.name, on:true} : null; }).filter(Boolean);
    } else sup = ci>=0? defaultSupports(ci) : [];
    usecases.push({id:'uc'+(i+1), name:c.name||'', isolate:c.isolate!=null&&tsBool(c.isolate),
      supports:sup, concManual:conc!=null, activeUsers:users||null, config:out, snapshot:{}});
  }
  const j={schema:'gpuscale.net/5', engine:ENGINE_VERSION, studio:STUDIO_VERSION,
    name: g.name!=null? tsDec(g.name) : 'Shared project',
    mode: g.mode!=null && /^norm/i.test(tsDec(g.mode))? 'normal' : 'advanced',
    config:cfg, project:{active:0, usecases}};
  const uniq=[...new Set(unknown)];
  if(uniq.length) notes.push(`ignored unknown key${uniq.length>1?'s':''}: ${uniq.join(', ')}`);
  return {json:j, notes};
}

/* ============ MCP SERVER (tools/mcp_server.js) ============ */
/* ---------------------------------------------------------------------------
   Everything above this line is the studio. Everything below is the interface.
   --------------------------------------------------------------------------- */

const PROTOCOL_DEFAULT = '2024-11-05';
const KNOWN_PROTOCOLS = ['2025-06-18', '2025-03-26', '2024-11-05'];
const SITE = 'https://gpuscale.net/';
const MIRROR = 'https://mahmoudyassine.github.io/gpuscale/';

/* ---------- library lookup: forgiving on input, exact on output ---------- */
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9.]+/g, '');
function pick(list, query, what, key = 'name') {
  const q = norm(query);
  if (!q) throw new Err(`${what} is required`);
  const names = list.map(x => String(key ? x[key] : x));
  const idx = names.map((s, i) => [norm(s), i]);
  let hits = idx.filter(h => h[0] === q);
  if (!hits.length) hits = idx.filter(h => h[0].startsWith(q));
  if (!hits.length) hits = idx.filter(h => h[0].includes(q));
  if (!hits.length) {
    const near = names.filter(n => norm(n).includes(q.slice(0, 4))).slice(0, 6);
    throw new Err(`${what} "${query}" is not in the library.` +
      (near.length ? ` Did you mean: ${near.join(', ')}?` : '') +
      ` Call list_library to see every valid name.`);
  }
  return { entry: list[hits[0][1]], name: names[hits[0][1]], ambiguous: hits.length > 1 };
}
class Err extends Error {}

/* ---------- build the studio's UC array from a plain spec ---------- */
function buildUC(spec) {
  const notes = [];
  const g = pick(GPUS, spec.gpu, 'gpu');
  SETTINGS.selGpu = GPUS.indexOf(g.entry);
  if (g.ambiguous) notes.push(`"${spec.gpu}" matched more than one GPU; used ${g.name}`);
  SETTINGS.inPerW = clamp(spec.gpusPerWorker != null ? spec.gpusPerWorker : 8, 1, 72);
  const rk = String(spec.resilience || 'n').toLowerCase();
  SETTINGS.selResil = RESIL[rk] ? rk : 'n';
  if (spec.resilience && !RESIL[rk])
    notes.push(`resilience "${spec.resilience}" is not a pattern; used N (no redundancy)`);
  const t = spec.tuning || {};
  SETTINGS.inMfu = clamp(num(t.prefillMFU, 0.5), 0.1, 0.9);
  SETTINGS.inMbu = clamp(num(t.decodeMBU, 0.65), 0.2, 0.95);
  SETTINGS.inIc = clamp(num(t.interconnectEff, 0.85), 0.4, 1);
  SETTINGS.inOvh = clamp(num(t.frameworkOverheadMs, 30), 0, 200);
  SETTINGS.autoUtil = clamp(num(t.autoSizeUtilPct, 80), 50, 95);

  const list = Array.isArray(spec.usecases) && spec.usecases.length
    ? spec.usecases : [spec];
  UC = list.map((u, i) => {
    const f = {};
    let mdl = u.model, custom = null;
    if (mdl && typeof mdl === 'object' && mdl.custom) custom = mdl;
    const cs = u.preset != null ? pick(CASES.filter(c => !/^Custom/.test(c.name)), u.preset, 'preset') : null;
    const c = cs ? cs.entry : null;
    if (custom) {
      f.chkCustom = true;
      f.cusParams = custom.params; f.cusActive = custom.active; f.cusHidden = custom.hidden;
      f.cusLayers = custom.layers; f.cusKvh = custom.kvHeads; f.cusHdim = custom.headDim;
      f.cusCtx = custom.ctx;
      f.selModel = 0;
    } else {
      const name = (typeof mdl === 'object' ? mdl.name : mdl) || (c && c.model);
      if (!name) throw new Err(`use case ${i + 1} has no model. Give "model", or a "preset" that suggests one.`);
      const m = pick(MODELS, name, 'model');
      if (m.ambiguous) notes.push(`"${name}" matched more than one model; used ${m.name}`);
      f.chkCustom = false; f.selModel = MODELS.indexOf(m.entry);
    }
    const wq = pick(QUANTS, u.weightQuant || 'FP8', 'weightQuant');
    const kq = pick(KV_QUANTS, u.kvQuant || 'FP8', 'kvQuant');
    f.selWQuant = QUANTS.indexOf(wq.entry);
    f.selKQuant = KV_QUANTS.indexOf(kq.entry);
    f.selCase = c ? CASES.indexOf(c) : -1;

    f.inSeq = num(u.residentSeq, c ? c.resident : 4096);
    f.inOut = num(u.visibleOut, c ? c.visibleOut : 400);
    f.inCache = clamp(num(u.sharedPrefixPct, (c && c.cachePct) || 0), 0, 95);
    // conversation length: a preset that describes a session carries the shape
    const sh = (c && c.session) || null, se = u.session || null;
    f.slMin = num(se && se.callMinutes, sh ? sh.min : 5);
    f.slRate = num(se && se.tokensPerMinute, sh ? sh.tokMin : 200);
    f.slBase = num(se && se.baseTokens, sh ? sh.base : Math.max(0, f.inSeq - 1000));
    f.slBasis = se && /^(mean|avg)/i.test(String(se.basis || '')) ? 'mean' : 'peak';
    if (se && se.callMinutes != null && u.residentSeq == null && f.slMin > 0 && f.slRate > 0)
      f.inSeq = Math.round(f.slBase + f.slRate * f.slMin / (f.slBasis === 'mean' ? 2 : 1));

    let rz = u.reasoning;
    if (rz == null) rz = c ? (c.reasonTok ? { mode: 'Custom', tokens: c.reasonTok }
                                          : { mode: c.reasoning || 'None' }) : { mode: 'None' };
    if (typeof rz === 'string') rz = { mode: rz };
    f.selReason = REASON_TOK[rz.mode] !== undefined ? rz.mode : 'None';
    f.inReasonTok = rz.mode === 'Custom' && rz.tokens != null ? rz.tokens : (REASON_TOK[f.selReason] || 0);
    f.chkExtend = rz.extendsKV !== false;

    f.selPolicy = u.kvPolicy ? (/^(all|session|pinned)/i.test(u.kvPolicy) ? 'all' : 'running')
                             : (c && c.policy === 'all' ? 'all' : 'running');
    const slo = u.sloTargets || {};
    f.sloTtft = num(slo.ttftMs, c ? c.ttftTarget || 0 : 0);
    f.sloTps = num(slo.tps, c ? c.tpsTarget || 0 : 0);
    f.sloP95 = num(slo.p95s, c ? c.p95Target || 0 : 0);

    const tr = (c && c.traffic) || {};
    const est = u.estimator || {};
    f.ccTurns = num(est.turnsPerHour, tr.turns || 8);
    f.ccShare = num(est.pctTurnsLLM, 100);
    f.ccCalls = num(est.callsPerTurn, tr.calls || 1.5);
    f.ccBurst = num(est.burst, tr.burst || 1.5);
    f.ccDur = num(est.callDurS, tr.durS || 0);
    const users = u.activeUsers != null ? Math.max(1, Math.round(+u.activeUsers)) : null;
    f.nrmUsers = users || 200;
    f.ccSessions = f.nrmUsers;

    let conc = u.concurrentCalls != null ? Math.max(1, Math.round(+u.concurrentCalls)) : null;
    const manual = conc != null;
    if (conc == null) {
      if (tr.direct) conc = f.nrmUsers;
      else {
        const dur = f.ccDur > 0 ? f.ccDur : 20;
        conc = Math.max(1, Math.ceil(f.nrmUsers * f.ccTurns * (f.ccShare / 100) * f.ccCalls * dur / 3600 * f.ccBurst));
      }
    }
    f.inConc = clamp(conc, 1, 10000);
    f.inBatch = clamp(num(u.maxBatchPerReplica, Math.min(64, f.inConc)), 1, 512);
    f.inWorkers = 1; f.inTp = 1; f.inPerW = SETTINGS.inPerW;
    f.inMfu = SETTINGS.inMfu; f.inMbu = SETTINGS.inMbu; f.inIc = SETTINGS.inIc; f.inOvh = SETTINGS.inOvh;

    let sup;
    if (u.supports === 'auto' || u.supports == null) sup = c ? defaultSupports(CASES.indexOf(c)) : [];
    else if (Array.isArray(u.supports)) sup = u.supports.map(x => {
      const kind = typeof x === 'string' ? x : x.kind;
      const k = TS_SUP.find(y => y.startsWith(String(kind).slice(0, 3).toLowerCase()));
      if (!k) { notes.push(`support kind "${kind}" is not one of ${TS_SUP.join(', ')}`); return null; }
      if (x && x.custom) return { kind: k, model: (SUP_DEFAULT(k) || {}).name, on: true, custom: x.custom };
      const want = typeof x === 'object' && x.model ? x.model : null;
      const m = want ? (SUPPORT.models.find(s2 => s2.kind === k && norm(s2.name) === norm(want))
                        || SUP_DEFAULT(k)) : SUP_DEFAULT(k);
      return m ? { kind: k, model: m.name, on: true } : null;
    }).filter(Boolean);
    else sup = [];

    return { id: 'uc' + (i + 1), name: u.name || (c ? c.name : null) || '', f,
             supports: sup, isolate: !!u.isolate, concManual: manual, modelManual: true,
             cards: 0, cardsKey: '', sliceU: 0 };
  });
  activeUc = 0;
  return notes;
}
const num = (v, d) => { const n = +v; return isFinite(n) && v !== null && v !== '' && v !== undefined ? n : d; };
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, +v || 0));
const r1 = x => Math.round(x * 10) / 10;
const strip = h => String(h).replace(/<[^>]+>/g, '').replace(/&[a-z]+;/g, ' ').replace(/\s+/g, ' ').trim();

/* ---------- the physics audit, shared with the link skill ---------- */
function auditProject(spec) {
  const errors = [], warnings = [], notes = [];
  const gpu = GPUS[SETTINGS.selGpu];
  UC.forEach(u => {
    const s = ucState(u, readHw()), who = u.name || u.id;
    const d = compute(s);
    const gen = s.reasonTok + s.visibleOut;
    if (d.effSeq > s.ctx)
      errors.push(`${who}: ${d.effSeq.toLocaleString()} resident + reasoning tokens exceed ${s.model.name}'s ${s.ctx.toLocaleString()}-token context.`);
    if (s.params * s.bytesW > 72 * s.gpuVram)
      errors.push(`${who}: one ${Math.round(s.params * s.bytesW)} GB copy of ${s.model.name} does not fit across 72x ${gpu.name}.`);
    if (s.sloP95 > 0 && s.sloTps > 0) {
      const need = 1.3 * (s.sloTtft / 1000 + gen / s.sloTps);
      if (need > s.sloP95 + 1e-9)
        errors.push(`${who}: the targets contradict each other. ${gen.toLocaleString()} tokens at ${s.sloTps} tok/s after ${s.sloTtft} ms is ${need.toFixed(1)} s at P95, above the ${s.sloP95} s promise.`);
    }
    const q = QUANTS[+u.f.selWQuant] || {};
    if (/Blackwell only/.test(q.hw || '') && !/Blackwell/.test(gpu.arch || ''))
      errors.push(`${who}: ${q.name} weights are ${q.hw}, and ${gpu.name} is ${gpu.arch}.`);
    if (s.resident >= 0.9 * s.ctx && s.ctx >= 32768)
      notes.push(`${who}: residentSeq is ~the whole context window. It is what one request HOLDS, not what the model can hold.`);
    if (uv(u.f, 'inCache') > 0)
      notes.push(`${who}: sharedPrefixPct assumes automatic prefix caching is enabled and the prompts really share that prefix.`);
    const live = s.policy === 'all' || (s.sloP95 > 0 && s.sloP95 <= 6);
    if (live && s.sloTps > 0 && s.sloTps < 30)
      notes.push(`${who}: a live path at ${s.sloTps} tok/s; speech and interactive paths want 30 or more.`);
    if (u.f.selCase >= 0) {
      const c = CASES[+u.f.selCase];
      if (c && c.supports) {
        const have = new Set((u.supports || []).map(x => x.kind));
        const miss = c.supports.filter(k => !have.has(k));
        if (miss.length) notes.push(`${who}: the ${c.name} preset normally attaches ${miss.join(', ')}; leaving them off under-sizes the fleet.`);
      }
    }
  });
  return { errors, warnings, notes };
}

/* ---------- solve, and describe the result the way the studio does ---------- */
function solveProject(spec) {
  const inputNotes = buildUC(spec);
  const audit = auditProject(spec);
  if (audit.errors.length)
    return { ok: false, errors: audit.errors, notes: audit.notes.concat(inputNotes) };

  // auto-size every pool, exactly as the Auto-size button does
  let prj = computeProject();
  prj.pools.forEach(p => {
    const r = solvePool(poolSolveState(p, prj.hw));
    if (!r.ok) return;
    p.members.forEach(mi => {
      UC[mi].f.inTp = r.tp; UC[mi].f.inWorkers = r.workers; UC[mi].f.inBatch = r.batch;
      UC[mi].cards = r.mode === 'sliced' ? 0 : (r.cards || 0);
      UC[mi].cardsKey = UC[mi].cards ? cardsKey(UC[mi], prj.hw) : '';
      UC[mi].sliceU = r.mode === 'sliced' ? r.sliceU : 0;
    });
  });
  prj = computeProject();

  const F = prj.fleet, hw = prj.hw;
  const pools = prj.pools.map((p, i) => {
    const d = p.d, s = p.state;
    return {
      models: s.model.name, weightQuant: s.wq.name, kvQuant: s.kq.name,
      useCases: p.members.map(mi => ucName(UC[mi])),
      tensorParallel: s.tp, replicas: d.replicas,
      servingCards: p.sliced ? 0 : d.replicas * s.tp,
      migSliced: p.sliced ? { units: p.sliced.units, perGpu: p.sliced.per || null } : null,
      batchPerReplica: s.batch, pooledConcurrency: s.concurrent, admitted: d.active, queued: d.queued,
      memory: { neededGB: r1(d.total), availableGB: r1(d.avail), usedPct: r1(d.total / d.avail * 100),
                weightsGB: r1(d.weightsAll), kvCacheGB: r1(d.kvTotal),
                activationsGB: r1(d.act * d.replicas), overheadGB: r1(d.fixed + d.multi),
                headroomGB: r1(d.headroom) },
      performance: { ttftMs: r1(d.ttft), perUserTps: r1(d.tps), aggregateTps: Math.round(d.agg),
                     interTokenMs: r1(d.itl), meanLatencyS: r1(d.latency), p95S: r1(d.p95) },
      fits: d.fits
    };
  });
  const useCases = [];
  prj.pools.forEach((p, pi) => p.perUc.forEach(x => useCases.push({
    name: ucName(x.uc), pool: pi, model: x.s.model.name,
    activeUsers: +x.uc.f.nrmUsers || null, concurrentCalls: x.s.concurrent,
    residentTokens: x.s.resident, visibleOut: x.s.visibleOut, reasoningTokens: x.s.reasonTok,
    kvPolicy: x.s.policy, sharedPrefixPct: Math.round((x.s.cachePct || 0) * 100),
    ttftMs: r1(x.d.ttft), perUserTps: r1(x.d.tps), p95S: r1(x.d.p95),
    targets: { ttftMs: x.s.sloTtft || null, tps: x.s.sloTps || null, p95s: x.s.sloP95 || null },
    slo: { ttft: x.s.sloTtft ? (x.d.slo.ttft.pass ? 'PASS' : 'FAIL') : 'off',
           tps: x.s.sloTps ? (x.d.slo.tps.pass ? 'PASS' : 'FAIL') : 'off',
           p95: x.s.sloP95 ? (x.d.slo.p95.pass ? 'PASS' : 'FAIL') : 'off' },
    sloMet: x.d.sloAll,
    supports: (x.uc.supports || []).map(sp => ({ kind: sp.kind, model: (supSpec(sp) || {}).name }))
  })));
  const info = RESIL[hw.resil] || RESIL.n;
  let recommendations = [];
  try {
    recommendations = sloOptScan(prj).map(r => ({
      level: r.lv === 'bad' ? 'critical' : r.lv === 'warn' ? 'warning' : 'info',
      title: strip(r.t), detail: strip(r.b)
    }));
  } catch (e) { /* recommendations are a bonus, never a failure */ }

  return {
    ok: true,
    verdict: !F.fits ? 'EXCEEDS_VRAM' : (F.sloAll ? 'FITS_AND_MEETS_SLOS' : 'FITS_BUT_MISSES_SLOS'),
    fleet: {
      gpu: hw.g.name, gpusPerNode: hw.perW, resilience: info.long,
      servingCards: F.servG, activeGpus: F.activeG,
      procuredNodes: F.procW, procuredGpus: F.procG, powerKwTdp: r1(F.kW),
      fits: F.fits, allSlosMet: F.sloAll
    },
    pools, useCases,
    supportingModels: (prj.sup && prj.sup.items || []).map(it => ({
      kind: it.kind, model: it.model.name, instances: it.instances,
      vramPerInstanceGB: it.model.vram })),
    supportingGpus: (prj.sup && prj.sup.gpus) || 0,
    recommendations,
    notes: audit.notes.concat(inputNotes),
    links: linksFor(spec),
    caveat: 'Peak closed-form estimates; production typically achieves 70-90%. Validate with vLLM bench or GenAI-Perf before committing hardware.'
  };
}

/* ---------- readable links, the form an agent can also write by hand ---------- */
function linksFor(spec) {
  const parts = [];
  if (spec.name) parts.push('name=' + spec.name);
  parts.push('gpu=' + GPUS[SETTINGS.selGpu].name);
  parts.push('perw=' + SETTINGS.inPerW);
  if (SETTINGS.selResil !== 'n') parts.push('resil=' + SETTINGS.selResil);
  UC.forEach(u => {
    const f = u.f, c = f.selCase >= 0 ? CASES[+f.selCase] : null;
    parts.push('uc=' + (u.name || 'Use case'));
    parts.push('model=' + (f.chkCustom
      ? 'custom:' + [f.cusParams, f.cusActive, f.cusHidden, f.cusLayers, f.cusKvh, f.cusHdim, f.cusCtx].join('/')
      : MODELS[+f.selModel].name));
    parts.push('quant=' + QUANTS[+f.selWQuant].name);
    parts.push('kv=' + KV_QUANTS[+f.selKQuant].name);
    if (c) parts.push('preset=' + c.name);
    const put = (k, v, base) => { if (base == null || +v !== +base) parts.push(k + '=' + v); };
    put('seq', +f.inSeq, c && c.resident);
    put('out', +f.inOut, c && c.visibleOut);
    if (+f.inCache) parts.push('cache=' + (+f.inCache));
    put('ttft', +f.sloTtft, c && c.ttftTarget);
    put('tps', +f.sloTps, c && c.tpsTarget);
    put('p95', +f.sloP95, c && c.p95Target);
    if (u.concManual) parts.push('conc=' + (+f.inConc));
    else if (+f.nrmUsers) parts.push('users=' + (+f.nrmUsers));
    if (u.isolate) parts.push('isolate=1');
  });
  const frag = '#p=t:' + parts.join(';').replace(/ /g, '+');
  return { studio: SITE + frag, mirror: MIRROR + frag,
           note: 'Open either link to see the same project in the studio, edit it, and export it.' };
}

/* ---------- tool definitions ---------- */
const SPEC_USECASE = {
  type: 'object',
  properties: {
    name: { type: 'string', description: 'Label for this workload.' },
    model: { description: 'Library model name, or {custom:true, params, active, hidden, layers, kvHeads, headDim, ctx}. Optional when preset is given, which suggests one.' },
    preset: { type: 'string', description: 'Workload preset name. Fills tokens, reasoning, SLO targets, KV policy, traffic shape and supporting models.' },
    weightQuant: { type: 'string', description: 'FP8 (default), BF16, NV FP4, MXFP4, INT8, Q4_K_M and 13 more.' },
    kvQuant: { type: 'string', description: 'FP8 (default), BF16, FP16, INT8, INT4.' },
    residentSeq: { type: 'integer', description: 'Tokens HELD per request: prompt + retained history + tool traces. NOT the model context window. Sizing on the window is the commonest way to over-order by 10x.' },
    visibleOut: { type: 'integer', description: 'Tokens the user sees per response.' },
    reasoning: { description: '"None" | "Light reasoning" | "Heavy reasoning" | {mode:"Custom", tokens:N, extendsKV:true}.' },
    sharedPrefixPct: { type: 'integer', description: 'Share of the sequence byte-identical every call, 0-95. Leave 0 unless the user gave a measured prefix-cache hit rate.' },
    session: { type: 'object', description: 'Conversations only: {callMinutes} sets the resident sequence from the call length. A named preset supplies the token rate and base.' },
    activeUsers: { type: 'integer', description: 'People using this at peak. Preferred over concurrentCalls when the user described people.' },
    concurrentCalls: { type: 'integer', description: 'Requests in flight at peak. Overrides activeUsers.' },
    kvPolicy: { type: 'string', description: '"running" (freed between turns) or "all" (pinned per session, correct for live voice).' },
    sloTargets: { type: 'object', description: '{ttftMs, tps, p95s}. tps is PER USER, never aggregate. 0 disables a check.' },
    supports: { description: '"auto" (the preset\'s own), [] for none, or ["embed","rerank","asr","tts","ocr","guard"].' },
    isolate: { type: 'boolean', description: 'Keep this use case in its own deployment even when another shares its model and precision.' }
  }
};
const SPEC = {
  type: 'object',
  required: ['gpu'],
  properties: {
    name: { type: 'string' },
    gpu: { type: 'string', description: 'One GPU type for the whole project. Library name, fuzzy match allowed.' },
    gpusPerWorker: { type: 'integer', description: 'GPUs per node: 8 = HGX, 4 = many OEM servers, 72 = NVL72 rack. Default 8.' },
    resilience: { type: 'string', description: 'n | n1 | n2 | nn | dr | drh | aa | aas | aas1 | aass | aan1 | nndr. Default n.' },
    tuning: { type: 'object', description: '{prefillMFU 0.5, decodeMBU 0.65, interconnectEff 0.85, frameworkOverheadMs 30, autoSizeUtilPct 80}.' },
    usecases: { type: 'array', items: SPEC_USECASE, description: 'One entry per workload. Two entries sharing a model, both precisions and the KV policy are served by ONE pooled deployment, as they would be in production.' }
  }
};

const TOOLS = [
  {
    name: 'size_project',
    description: 'Size a self-hosted LLM deployment: how many GPUs and nodes, whether it fits, and whether it keeps its latency promises. Solves tensor-parallel width, replica count and batch size, pools use cases that share a model and precision, attaches supporting models, applies a resilience pattern, and returns the fleet plus per-use-case SLO verdicts and recommendations. This is the whole gpuscale.net studio in one call. Use it for any question about GPU counts, VRAM fit, KV cache size, tokens per second, time to first token, or "can model X run on hardware Y".',
    inputSchema: SPEC
  },
  {
    name: 'compare_gpus',
    description: 'Size the SAME workload across several GPUs and rank them by procured GPUs, then by power. Answers "which card should we buy for this" without running size_project once per candidate.',
    inputSchema: {
      type: 'object', required: ['gpus', 'spec'],
      properties: {
        gpus: { type: 'array', items: { type: 'string' }, description: 'Candidate GPU names, 2 to 8 of them.' },
        spec: { type: 'object', description: 'A size_project spec. Its "gpu" field is replaced by each candidate in turn.' }
      }
    }
  },
  {
    name: 'audit_spec',
    description: 'Check a configuration for contradictions without sizing it: a context overflow, SLO targets that cannot all hold at once, a quantization the card cannot run, a resident sequence set to the whole context window. Returns errors (no hardware fixes these) and notes (legal but usually a mistake).',
    inputSchema: SPEC
  },
  {
    name: 'build_link',
    description: 'Turn a spec into a gpuscale.net URL that opens the whole project in the studio, where a human can edit it, export it or share it. The link carries the project inside the fragment; nothing is uploaded.',
    inputSchema: SPEC
  },
  {
    name: 'read_link',
    description: 'Decode a gpuscale.net share link (#p=t:, #p=j: or #p=z:) into the project it carries, and size it. Use this when a user pastes a link and asks what is in it or whether it is right.',
    inputSchema: {
      type: 'object', required: ['url'],
      properties: { url: { type: 'string', description: 'A gpuscale.net link or just its fragment.' } }
    }
  },
  {
    name: 'list_library',
    description: 'Every valid name the other tools accept. Call this before naming a model or GPU you are not certain of: an invented name is rejected, and a silently substituted one would be worse.',
    inputSchema: {
      type: 'object', required: ['kind'],
      properties: {
        kind: { type: 'string', enum: ['models', 'gpus', 'presets', 'quants', 'kv_quants', 'resilience', 'supports'] },
        filter: { type: 'string', description: 'Case-insensitive substring, e.g. "llama" or "h100".' }
      }
    }
  }
];

/* ---------- tool implementations ---------- */
function toolSize(args) {
  const r = solveProject(args);
  if (!r.ok) return { text: 'This configuration cannot work:\n' + r.errors.map(e => '  ERROR ' + e).join('\n'), data: r, isError: true };
  const f = r.fleet;
  const lines = [
    `${f.procuredNodes} node${f.procuredNodes > 1 ? 's' : ''} · ${f.procuredGpus} ${f.gpu} · ~${f.powerKwTdp} kW  (${f.resilience})`,
    `${r.verdict === 'FITS_AND_MEETS_SLOS' ? 'Fits and every SLO target is met.'
      : r.verdict === 'FITS_BUT_MISSES_SLOS' ? 'Fits, but at least one latency target is missed.'
      : 'Does not fit.'}`,
    `${f.servingCards} serving cards${r.supportingGpus ? ` + ${r.supportingGpus} shared GPUs for supporting models` : ''}.`, ''
  ];
  r.pools.forEach(p => lines.push(
    `  ${p.models} ${p.weightQuant}/${p.kvQuant}: TP${p.tensorParallel} x ${p.replicas} replica${p.replicas > 1 ? 's' : ''}` +
    ` = ${p.servingCards} cards, batch ${p.batchPerReplica}, ${p.memory.usedPct}% memory, ` +
    `${p.performance.ttftMs} ms first token, ${p.performance.perUserTps} tok/s per user` +
    (p.useCases.length > 1 ? `  [pooled: ${p.useCases.join(' + ')}]` : '')));
  lines.push('');
  r.useCases.forEach(u => lines.push(
    `  ${u.name}: ${u.concurrentCalls} concurrent · ttft ${u.ttftMs}/${u.targets.ttftMs || '-'} ms · ` +
    `${u.perUserTps}/${u.targets.tps || '-'} tok/s · p95 ${u.p95S}/${u.targets.p95s || '-'} s · ` +
    (u.sloMet ? 'SLOs met' : 'TARGET MISSED')));
  if (r.notes.length) lines.push('', 'Notes:', ...r.notes.map(n => '  · ' + n));
  if (r.recommendations.length) lines.push('', 'Recommendations:',
    ...r.recommendations.slice(0, 4).map(x => `  [${x.level}] ${x.title}`));
  lines.push('', 'Open in the studio: ' + r.links.studio, '', r.caveat);
  return { text: lines.join('\n'), data: r };
}

function toolCompare(args) {
  const cands = (args.gpus || []).slice(0, 8);
  if (cands.length < 2) throw new Err('give at least two GPUs to compare');
  const rows = cands.map(name => {
    try {
      const r = solveProject(Object.assign({}, args.spec, { gpu: name }));
      if (!r.ok) return { gpu: name, ok: false, reason: r.errors[0] };
      return { gpu: r.fleet.gpu, ok: true, procuredGpus: r.fleet.procuredGpus,
               procuredNodes: r.fleet.procuredNodes, powerKwTdp: r.fleet.powerKwTdp,
               fits: r.fleet.fits, allSlosMet: r.fleet.allSlosMet,
               topology: r.pools.map(p => `TP${p.tensorParallel}x${p.replicas}`).join(' + ') };
    } catch (e) { return { gpu: name, ok: false, reason: e.message }; }
  });
  const good = rows.filter(r => r.ok && r.fits).sort((a, b) =>
    (b.allSlosMet - a.allSlosMet) || (a.procuredGpus - b.procuredGpus) || (a.powerKwTdp - b.powerKwTdp));
  const lines = ['Ranked by GPUs procured, then power. Only configurations that fit are ranked.', ''];
  good.forEach((r, i) => lines.push(
    `  ${i + 1}. ${r.gpu}: ${r.procuredNodes} nodes · ${r.procuredGpus} GPUs · ~${r.powerKwTdp} kW · ${r.topology}` +
    (r.allSlosMet ? '' : '  (misses an SLO target)')));
  rows.filter(r => !r.ok || !r.fits).forEach(r => lines.push(
    `     ${r.gpu}: ${r.ok ? 'does not fit' : r.reason}`));
  return { text: lines.join('\n'), data: { ranked: good, rejected: rows.filter(r => !r.ok || !r.fits) } };
}

function toolAudit(args) {
  buildUC(args);
  const a = auditProject(args);
  const clean = !a.errors.length && !a.notes.length;
  const lines = clean ? ['No contradictions found.'] : [];
  a.errors.forEach(e => lines.push('ERROR  ' + e));
  a.notes.forEach(n => lines.push('note   ' + n));
  return { text: lines.join('\n'), data: a, isError: a.errors.length > 0 };
}

function toolLink(args) {
  const notes = buildUC(args);
  const a = auditProject(args);
  if (a.errors.length)
    return { text: 'No link produced; this configuration cannot work:\n' + a.errors.map(e => '  ERROR ' + e).join('\n'),
             data: { errors: a.errors }, isError: true };
  const l = linksFor(args);
  return { text: [l.studio, '', 'Mirror (for networks that block gpuscale.net):', l.mirror,
                  ...(a.notes.length ? ['', 'Notes:', ...a.notes.map(n => '  · ' + n)] : []),
                  ...(notes.length ? notes.map(n => '  · ' + n) : [])].join('\n'),
           data: Object.assign({}, l, { notes: a.notes.concat(notes) }) };
}

function toolRead(args) {
  const url = String(args.url || '');
  const i = url.indexOf('#p=');
  if (i < 0) throw new Err('that does not look like a GPUscale link: no "#p=" fragment.');
  const payload = url.slice(i + 3);
  if (payload.startsWith('t:')) {
    const r = parseTextShare(payload.slice(2));
    if (r.error) throw new Err(r.error);
    const spec = fromPayload(r.json);
    const sized = solveProject(spec);
    return { text: describeSpec(spec) + '\n\n' + (sized.ok ? toolSize(spec).text : sized.errors.join('\n')),
             data: { spec, sized } };
  }
  throw new Err('this build reads the readable "#p=t:" form. For "#p=z:" or "#p=j:" links, ' +
                'decode with scripts/gpuscale_url.py from the gpuscale-link skill, or open the link in a browser.');
}
function fromPayload(j) {
  const g = j.config || {};
  return {
    name: j.name, gpu: g.gpu, gpusPerWorker: (g.hardware || {}).gpusPerWorker,
    resilience: (g.hardware || {}).resilience, tuning: g.tuning,
    usecases: (j.project.usecases || []).map(u => {
      const c = u.config || {};
      return { name: u.name, model: c.model && c.model.custom ? Object.assign({ custom: true }, c.model) : (c.model || {}).name,
               preset: c.preset, weightQuant: c.weightQuant, kvQuant: c.kvQuant,
               residentSeq: c.residentSeq, visibleOut: c.visibleOut,
               sharedPrefixPct: c.sharedPrefixPct, session: c.session,
               reasoning: c.reasoning, kvPolicy: c.kvPolicy, sloTargets: c.sloTargets,
               concurrentCalls: u.concManual ? c.concurrentCalls : null,
               activeUsers: u.activeUsers, isolate: u.isolate,
               supports: (u.supports || []).map(s => s.kind) };
    })
  };
}
function describeSpec(spec) {
  return `Project "${spec.name || 'untitled'}" · ${spec.gpu} · ${spec.gpusPerWorker || 8} GPU/node · ` +
         `resilience ${spec.resilience || 'n'} · ${spec.usecases.length} use case(s)`;
}

function toolList(args) {
  const kind = args.kind, filt = (args.filter || '').toLowerCase();
  const keep = s => !filt || String(s).toLowerCase().includes(filt);
  let rows = [], data = [];
  if (kind === 'models') {
    data = MODELS.filter(m => keep(m.name + ' ' + (m.arch || '') + ' ' + (m.dev || '')));
    rows = data.map(m => `${m.name} · ${m.params}B total / ${m.active}B active · ctx ${m.ctx.toLocaleString()} · ${m.arch || ''}`);
  } else if (kind === 'gpus') {
    data = GPUS.filter(g => keep(g.name + ' ' + (g.arch || '')));
    rows = data.map(g => `${g.name} · ${g.vram} GB · ${g.bw} TB/s · ${g.tflops} dense TF · ${g.watts} W · ${g.arch || ''}`);
  } else if (kind === 'presets') {
    data = CASES.filter(c => !/^Custom/.test(c.name) && keep(c.name));
    rows = data.map(c => `${c.name} · seq ${c.resident} · out ${c.visibleOut} · SLO ${c.ttftTarget}ms/${c.tpsTarget}tps/${c.p95Target}s` +
      (c.model ? ` · suggests ${c.model}` : '') + (c.policy === 'all' ? ' · KV pinned per session' : ''));
  } else if (kind === 'quants') {
    data = QUANTS.filter(q => keep(q.name));
    rows = data.map(q => `${q.name} · ${q.bytes} bytes/param · ${q.quality || ''} · ${q.hw || ''}`);
  } else if (kind === 'kv_quants') {
    data = KV_QUANTS.filter(q => keep(q.name));
    rows = data.map(q => `${q.name} · ${q.bytes} bytes/element`);
  } else if (kind === 'resilience') {
    data = Object.keys(RESIL).filter(k => keep(k + RESIL[k].long)).map(k => ({ key: k, label: RESIL[k].label, long: RESIL[k].long }));
    rows = data.map(r => `${r.key} · ${r.label} · ${r.long}`);
  } else if (kind === 'supports') {
    data = SUPPORT.models.filter(m => keep(m.name + ' ' + m.kind));
    rows = data.map(m => `${m.kind} · ${m.name} · ${m.vram} GB/instance · ~${m.cap} concurrent/instance`);
  } else throw new Err('unknown kind: ' + kind);
  return { text: `${rows.length} ${kind}:\n` + rows.map(r => '  ' + r).join('\n'), data };
}

const IMPL = { size_project: toolSize, compare_gpus: toolCompare, audit_spec: toolAudit,
               build_link: toolLink, read_link: toolRead, list_library: toolList };

/* ---------- resources: the method, for an agent that wants to read it ---------- */
const RESOURCES = [
  { uri: 'gpuscale://manual', name: 'GPUscale manual', mimeType: 'text/plain',
    description: 'How the studio sizes a fleet: the three currencies, the closed forms, the solver, resilience patterns.' },
  { uri: 'gpuscale://formulas', name: 'Engine formulas', mimeType: 'text/plain',
    description: 'Every closed form the engine evaluates, with units.' },
  { uri: 'gpuscale://conventions', name: 'Sizing conventions', mimeType: 'text/plain',
    description: 'The rules that decide whether a configuration is right: per-request fields, resident vs context, tok/s per user.' }
];
const RESOURCE_TEXT = {
  'gpuscale://formulas': `GPUscale engine v${ENGINE_VERSION} closed forms (all memory in GB, params in billions)

weights        = params x bytes_per_weight                     per replica
kv_per_token   = 2 x layers x kv_heads x head_dim x bytes_kv / 1e9
                 (sliding-window hybrids mix a full-attention term with a
                  windowed one, so their per-token cost falls with context)
cached         = floor(resident x shared_prefix_fraction)      prefilled once,
                 held once per replica
unique         = max(0, effSeq - cached)                       charged per call
effSeq         = resident + reasoning (when reasoning extends the KV cache)
kv_total       = admitted x unique x kv_per_token + replicas x cached x kv_per_token
activations    = min(effSeq, 8192) x hidden x 12 x bytes_w / 1e9   per replica
overhead       = 5 GB fixed + replicas x (TP-1) x 15 GB NCCL buffers
need           = replicas x (weights + activations) + kv_total + overhead
avail          = replicas x TP x VRAM_per_GPU

BW_eff         = BW_TBs x TP x interconnect x MBU x 1000        GB/s
admitted       = min(concurrency, batch x replicas)             running batch
                 concurrency                                    KV pinned
tok_s_per_user = BW_eff / (active_params x bytes_w + batch_per_replica x effSeq x kv_per_token)
TTFT_ms        = 2 x (resident - cached) x active_params / (TFLOPS x TP x MFU)
latency_s      = (TTFT + framework_overhead)/1000 + (reasoning + visible) / tok_s
p95_s          = 1.3 x latency_s                                fixed convention

concurrency    = ceil(users x turns x share x calls x duration/3600 x burst)

Defaults: MFU 0.5, MBU 0.65, interconnect 0.85 in-island and 0.70 across nodes,
framework overhead 30 ms, auto-size memory target 80%.
All figures are peak estimates; production typically achieves 70-90%.`,
  'gpuscale://conventions': `Getting a GPUscale configuration right

1. residentSeq is tokens HELD per request: system prompt + retrieved context +
   conversation so far + tool traces. It is NOT the model's context window.
   A 1M-context model serving 8K conversations is residentSeq 8192. Sizing on
   the window is the commonest way to over-order hardware by 10x.
2. Every field describes ONE model call. An agent making forty tool calls per
   task is forty requests, not one enormous one. Use activeUsers plus the
   preset's traffic shape, or concurrentCalls.
3. tps targets are PER USER streaming speed, never aggregate throughput.
4. Prefer activeUsers over concurrentCalls when the user described people.
   Turning headcount into concurrency is what the traffic estimator is for.
5. For voice and contact-centre workloads ask how long a call lasts and set
   session.callMinutes: a conversation holds its transcript, and those presets
   pin KV for the whole session.
6. Leave sharedPrefixPct at 0 unless the user gave a measured prefix-cache hit
   rate AND their stack has automatic prefix caching enabled.
7. KV cache at FP8 unless told otherwise: it halves the cache against BF16 with
   negligible quality loss.
8. Never invent a model or GPU name. Call list_library. If the model is genuinely
   absent, pass a custom geometry and say that you did.
9. Do not pin tensor parallelism, workers or batch size: the solver chooses them,
   and a guess is either ignored or wrong.
10. State your assumptions. GPU, quantization and resilience pattern are usually
    your choices, not the user's.`,
  'gpuscale://manual': `The GPUscale manual lives at ${SITE}manual.html

It covers, with worked examples and diagrams:
  1 Quick start
  2 How the studio thinks: three currencies, one model call, pools
  3 The interface, control by control
  4 Reading the results
  5 The mathematics, in full, with a worked example checkable on a calculator
  6 The auto-size solver and its invariants
  7 Pooling, co-residency and MIG slicing
  8 Supporting models
  9 Resilience patterns
 10 The SLO optimiser
 11 Workload presets and the evidence behind them
 12 Exports, share links and AI assistants
 13 Libraries and how to extend them
 14 Accuracy, limits and validation
 15 Glossary

Call the gpuscale://formulas resource for the closed forms, or
gpuscale://conventions for the rules that decide whether a configuration is
right.`
};

/* ---------- JSON-RPC 2.0 over stdio, one message per line ---------- */
function send(msg) { process.stdout.write(JSON.stringify(msg) + '\n'); }
function reply(id, result) { if (id !== undefined && id !== null) send({ jsonrpc: '2.0', id, result }); }
function fail(id, code, message) { if (id !== undefined && id !== null) send({ jsonrpc: '2.0', id, error: { code, message } }); }

function handle(msg) {
  const { id, method, params } = msg;
  try {
    switch (method) {
      case 'initialize': {
        const want = (params || {}).protocolVersion;
        return reply(id, {
          protocolVersion: KNOWN_PROTOCOLS.includes(want) ? want : PROTOCOL_DEFAULT,
          capabilities: { tools: {}, resources: {} },
          serverInfo: { name: 'gpuscale', version: STUDIO_VERSION,
                        title: 'GPUscale · LLM GPU capacity sizing' },
          instructions:
            'GPUscale sizes self-hosted LLM deployments with closed-form arithmetic: no model, no ' +
            'network, no telemetry. Call list_library before naming a model or GPU you are unsure of. ' +
            'Call size_project for any question about GPU counts, VRAM fit, tokens per second or SLO ' +
            'feasibility, and quote its numbers rather than estimating. Read gpuscale://conventions ' +
            'once: residentSeq is tokens held per request, not the context window, and every field ' +
            'describes one model call. Hand the user the link size_project returns so they can check ' +
            'and edit the sizing themselves.'
        });
      }
      case 'notifications/initialized': return;
      case 'ping': return reply(id, {});
      case 'tools/list': return reply(id, { tools: TOOLS });
      case 'resources/list': return reply(id, { resources: RESOURCES });
      case 'resources/read': {
        const uri = (params || {}).uri;
        const text = RESOURCE_TEXT[uri];
        if (text === undefined) return fail(id, -32602, 'unknown resource: ' + uri);
        return reply(id, { contents: [{ uri, mimeType: 'text/plain', text }] });
      }
      case 'tools/call': {
        const name = (params || {}).name, args = (params || {}).arguments || {};
        const fn = IMPL[name];
        if (!fn) return fail(id, -32602, 'unknown tool: ' + name);
        let out;
        try {
          out = fn(args);
        } catch (e) {
          // a bad argument is the caller's problem to fix, not a protocol error:
          // report it inside the result so the model can read it and retry
          return reply(id, { content: [{ type: 'text', text: (e instanceof Err ? '' : 'error: ') + e.message }],
                             isError: true });
        }
        const res = { content: [{ type: 'text', text: out.text }] };
        if (out.data !== undefined) res.structuredContent = out.data;
        if (out.isError) res.isError = true;
        return reply(id, res);
      }
      default:
        return fail(id, -32601, 'method not found: ' + method);
    }
  } catch (e) {
    return fail(id, -32603, e && e.message ? e.message : String(e));
  }
}

let buf = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => {
  buf += chunk;
  let nl;
  while ((nl = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, nl).trim();
    buf = buf.slice(nl + 1);
    if (!line) continue;
    let msg;
    try { msg = JSON.parse(line); }
    catch (e) { send({ jsonrpc: '2.0', id: null, error: { code: -32700, message: 'parse error' } }); continue; }
    if (Array.isArray(msg)) msg.forEach(handle); else handle(msg);
  }
});
process.stdin.on('end', () => process.exit(0));

/* A one-shot mode for humans and CI: node gpuscale-mcp.mjs --self-test */
if (process.argv.includes('--self-test')) {
  const spec = { name: 'self test', gpu: 'H200 141GB NVL', gpusPerWorker: 8, resilience: 'n1',
    usecases: [{ name: 'Support chat', model: 'Llama 3.3 70B', preset: 'Simple RAG', activeUsers: 2000 }] };
  const r = toolSize(spec);
  process.stdout.write(r.text + '\n');
  process.exit(r.data && r.data.ok ? 0 : 1);
}
